(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-green-code-learning-to-optimize-ener-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-1\">一 · 现场：一条仓库级补全请求在夜里烧掉的钱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-2\">二 · 旧方案的三根支柱，以及它们各自漏掉的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-3\">三 · 能耗账本：预填与解码为什么必须分开记</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-4\">四 · 为什么“提前停”在代码任务上不是拍脑袋</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-5\">五 · 旧方案的吞吐账：批调度与 KV 缓存为何救不了能效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-6\">六 · 非改不可的工程判断：能效必须落到解码策略上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-7\">七 · 负载形态的三个可测维度：输入长度、并发与批大小</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-8\">八 · SLO 与长尾：能耗优化的可行域由尾延迟划定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-9\">九 · 负载塑造方案：批大小如何改变能耗最优解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-10\">十 · 方案反过来限制负载：策略如何改变请求形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-11\">十一 · 可核查的测量清单与 Blackwell 上的落地口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-12\">十二 · 当“提前停”遇上真实负载：策略的适用边界与测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-13\">十三 · 从能耗目标反推 kernel 选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-14\">十四 · 四种数值格式的误差结构与适用位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-15\">十五 · tcgen05、TMEM 与 2-SM MMA 的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-16\">十六 · 量化与 KV 缓存的耦合代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-17\">十七 · 精度档位与能耗度量的可复现性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-18\">十八 · 把精度决策嵌进策略循环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-19\">十九 · 能效策略在数值精度与 Blackwell 算子栈上的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-20\">二十 · 显存账本的三层结构与可复算预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-21\">二十一 · 分页与块表：把 KV 从连续数组变成可回收的页</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-22\">二十二 · 压缩与复用：量化 KV、结构裁剪、前缀缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-23\">二十三 · 卸载与带宽瓶颈的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-24\">二十四 · 把账本接回能耗目标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-25\">二十五 · 提前终止策略在显存账本上的边界：省的是解码算力，不是 KV 驻留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-26\">二十六 · 连续批处理：把“提前终止”变成调度信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-27\">二十七 · Chunked prefill：预填与解码的能耗结构差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-28\">二十八 · 优先级与抢占：尾延迟的源头在队列而非算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-29\">二十九 · 分离式预填/解码：把两种能耗结构放到不同硬件档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-30\">三十 · 时延与吞吐的取舍：把策略阈值当作调度旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-31\">三十一 · 尾延迟怎么压：从测量缺口到工程闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-32\">三十二 · 能效策略撞上批调度：边界、失效条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-33\">三十三 · 并行切分的四轴与代码生成负载的匹配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-34\">三十四 · All-Reduce 与 All-to-All 的代价结构差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-35\">三十五 · NIXL 传输与分离式预填/解码的通信面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-36\">三十六 · 通信何时成为瓶颈的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-37\">三十七 · 代码生成负载下的切分决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-38\">三十八 · 并行拓扑的能耗边界：通信何时吃掉 GREEN-CODE 的收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-39\">三十九 · 精度塌陷：从“通过率掉点”到可归因的数值链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-40\">四十 · OOM 与批抖动：容量边界上的连锁反应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-41\">四十一 · 尾延迟：策略不确定性与解码长尾的叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-42\">四十二 · 静默降级：没有报错的能效回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-43\">四十三 · 回滚与定位：把策略版本当作可回退的部署单元</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-44\">四十四 · 能效策略的失效边界：从“提前终止”到“静默降级”的连锁诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-45\">四十五 · 度量口径：预填与解码必须分开记账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-46\">四十六 · 硬件档位：没有档位就没有能耗数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-47\">四十七 · batch 与并发：能耗的分母陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-48\">四十八 · 指标族：TTFT、TPOT、吞吐、功耗各自回答什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-49\">四十九 · 哪些提升不可比：四条硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-50\">五十 · 把口径写成可执行的采集清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-51\">五十一 · 迁移的第一道门槛：策略的输入信号从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-52\">五十二 · 能耗度量的跨平台不可比性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-53\">五十三 · 与量化、KV cache 管理的叠加关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-54\">五十四 · 领域迁移：哪些代码形态不适用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-55\">五十五 · 规模上限与容量规划的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-green-code-learning-to-optimize-ener-2025-sec-56\">五十六 · 迁移到别的模型与领域时，先看哪几个耦合点会断</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:542px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 541.9 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">接收编程问题描述与必要上下文，构造提示并送入模型进行预填。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预填阶段完成上下文编码并建立 KV 缓存，为后续解码提供条件。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码阶段按学习到的能效策略逐步生成代码 token，动态控制生成长度。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">生成结束后对代码进行功能正确性校验，同时记录推理能耗。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">将质量与能耗结果反馈至策略学习环节，更新生成策略参数。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-1\">一 · 现场：一条仓库级补全请求在夜里烧掉的钱</h3>\n<p>设想一个真实在线服务：某团队的 IDE 插件把光标处的文件、若干跨文件符号、最近的编辑历史拼成一条长提示，送到推理集群。请求形态是典型的仓库级代码补全——上下文动辄数万 token，输出却往往只有几十行。白天它表现为延迟敏感型负载，夜里则被 CI 里的批量补全与工具调用循环接管，变成吞吐敏感型负载。运维看到的账单结构非常不均衡：预填阶段把整段上下文编码进 KV 缓存，一次前向就把 GPU 的算力与显存带宽吃满；解码阶段则一个 token 一个 token 地往外挤，每步都要读一遍权重与 KV 缓存，却只产出极少的有效信息。更要命的是，模型并不知道什么时候该停：它会在一个已经语义完备的函数体后面继续补注释、补防御性分支、补重复的样板代码，而这些 token 对通过测试用例毫无贡献，却实打实地消耗了显存带宽与功耗。</p>\n<p>这就是 GREEN-CODE 面对的问题现场。论文的出发点不是“模型不够强”，而是“推理行为没有被当作可优化的对象”。在此之前，主流推理栈把能效当作模型规模、硬件档位与批大小的副产品：想省电就换小模型，想快就加卡，想稳就加批。这套做法在代码生成上失效，因为代码任务的能耗结构由上下文长度与生成长度共同决定，而这两者都不是模型参数能决定的。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-2\">二 · 旧方案的三根支柱，以及它们各自漏掉的账</h3>\n<p>论文之前，工程侧的能效手段大致落在三处。第一根支柱是<strong>模型侧缩放</strong>：用更小的模型、更低的数值精度（FP8、INT8）换取单位 token 的更低价。这条路的问题在于，代码生成的质量对数值精度与模型容量敏感，量化带来的通过率损失往往要靠更长的生成来补偿，于是省下的算力又被多生成的 token 吃掉。第二根支柱是<strong>批调度</strong>：连续批处理把不同请求拼进同一个 decode step，提高 GPU 利用率。但仓库级补全的上下文长度分布极不均匀，长请求会把 KV 缓存撑爆，短请求则被长请求拖住，批内 token 的有效产出率下降。第三根支柱是<strong>KV 缓存管理</strong>：分页、前缀复用、驱逐策略。它确实降低了显存占用，但显存占用下降并不自动等于能耗下降——预填阶段的算力开销与解码阶段的带宽开销是两种不同的账。</p>\n<p>三根支柱共同的盲点在于：它们都作用在“系统怎么跑”这一层，而没有作用在“模型生成多少”这一层。生成长度是一个由解码策略决定的变量，却长期被固定为“生成到 EOS 或到 max_tokens 为止”。在代码场景里，这个固定策略的代价尤其高：一个补全请求的真实有效输出可能只有 20 个 token，但模型会生成 200 个。多出来的 180 个 token 在解码阶段是纯粹的带宽与功耗开销，在预填阶段则毫无影响——这正是论文强调“预填与解码能耗结构差异明显”的工程含义。</p>\n<div class=\"formula\">$$\\min_{\\pi}\\ \\mathbb{E}_{x\\sim\\mathcal{D}}\\left[\\mathcal{E}(\\pi,x)\\right]\\quad \\text{s.t.}\\quad \\mathbb{E}_{x\\sim\\mathcal{D}}\\left[\\mathbb{1}\\{\\text{pass}(\\pi,x)\\}\\right]\\ge \\tau$$</div>\n<p>这个形式化目标把问题从“选哪个模型”搬到了“选哪个解码策略 π”。约束项是通过率不低于阈值 τ，目标项是期望能耗。注意它的工程含义：能耗不是一个可以无限压缩的量，它被质量锁死；而质量不是一个可以无限追求的量，它被能耗预算锁死。这条约束线正是旧方案缺失的东西——旧方案要么牺牲质量换能耗，要么牺牲能耗换质量，没有一个显式的、可调的平衡点。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-3\">三 · 能耗账本：预填与解码为什么必须分开记</h3>\n<p>论文的框架把能耗度量拆成预填与解码两段，这不是形式上的拆分，而是两种截然不同的硬件代价。预填阶段是一次大规模矩阵乘，算力密集，其能耗大致随上下文长度线性增长，且与批内请求的上下文总长度相关；解码阶段是逐 token 的自回归，每步只做一次小矩阵乘加一次全量 KV 缓存读取，带宽密集，其能耗随生成 token 数线性增长，且与 KV 缓存驻留位置（HBM 还是片上）强相关。用一句工程判断概括：预填烧的是算力，解码烧的是带宽。</p>\n<p>把这两笔账混在一起记，会得出错误的优化方向。假设一个服务里预填占能耗七成、解码占三成，那么压缩生成长度只能动那三成；反过来，如果解码占七成，那么优化预填的收益就有限。论文的材料没有给出具体比例，但它明确指出“预填与解码的能耗结构差异明显”，并要求度量覆盖两阶段——这本身就是一个部署判断：任何能效优化方案，如果不分阶段记账，就无法判断收益来自哪里，也就无法做容量规划。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>硬件瓶颈</th><th>能耗随什么增长</th><th>旧方案的盲点</th></tr></thead><tbody><tr><td>预填</td><td>算力（矩阵乘）</td><td>上下文总长度</td><td>批内长请求拖累短请求</td></tr><tr><td>解码</td><td>显存带宽（KV 读取）</td><td>生成 token 数</td><td>固定 max_tokens 导致过量生成</td></tr></tbody></table>\n<p>具体例子：一条仓库级补全请求，上下文 3 万 token，模型实际只需生成 30 个 token 就能通过测试，但解码策略固定跑到 256 个 token。预填那 3 万 token 的账在请求进入时就已付清，无法通过解码策略挽回；而多出的 226 个 token 在解码阶段每一步都要读一遍 KV 缓存，这部分开销完全由“生成多少”这个变量决定。论文的策略正是作用在后者：在置信度高时提前终止，在不确定时继续生成。它不改变预填的账，但它把解码的账从固定成本变成了可变成本。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-4\">四 · 为什么“提前停”在代码任务上不是拍脑袋</h3>\n<p>提前终止生成本身不是新想法，但在代码生成上它有特殊结构。代码的正确性由测试用例判定，而不是由语言模型的概率判定；这意味着“模型觉得写完了”与“代码真的能跑”之间存在一个可观测的间隙。论文的策略学习正是利用这个间隙：采样生成轨迹，跑测试用例得到通过标志，把通过率与能耗一起作为反馈信号。策略在置信度高时提前停，赌的是“停在这里仍然能通过”；在不确定时继续生成，赌的是“多写几个 token 能换来通过”。</p>\n<p>伪代码层面的思路是：对每个请求，解码器在每一步拿到当前 token 的置信度与已生成长度，策略网络据此决定继续或终止；终止后立即运行测试用例，得到 pass 标志与两阶段能耗；这对（pass, energy）样本回流到策略更新。代价在于测试用例的执行开销——论文材料明确指出“校验开销未计入能耗统计”，这是一个必须记住的工程缺口：如果测试本身很重（编译、链接、跑集成测试），那么策略省下的解码能耗可能被校验开销抵消，甚至在低延迟 SLO 下不可接受。</p>\n<p>另一个代价是策略的泛化边界。策略学习依赖测试用例反馈，这在有单测的仓库里可行，但在无测试用例的代码补全场景（大量 IDE 补全请求根本没有可执行的测试）中，通过标志无法获得，策略就失去了训练信号。论文材料把这一点列为局限，工程含义是：这套方法最适合落在“有可执行验证”的环节，例如 CI 辅助的批量补全、工具调用循环中的代码修复，而不是纯粹的实时代码补全。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-5\">五 · 旧方案的吞吐账：批调度与 KV 缓存为何救不了能效</h3>\n<p>连续批处理提高的是 GPU 利用率，不是能效。这两者在代码生成上会分叉：当批内请求的生成长度差异很大时，短请求早早结束，长请求继续占用批槽，GPU 在每个 decode step 上做的有效工作比例下降。更长的生成意味着更多的 decode step，而每个 step 的固定开销（权重读取、调度、同步）并不随有效 token 数减少。于是吞吐看似上去了，单位有效 token 的能耗却没有改善。论文的材料没有给出批大小与并发配置，因此无法量化这一点，但它的框架把“生成长度”作为优化变量，实际上绕开了批调度的局限：与其在批内做负载均衡，不如让每个请求少生成。</p>\n<p>KV 缓存管理的处境类似。分页与驱逐降低了显存占用，使更多请求能同时驻留，从而提升吞吐；但解码阶段的能耗主要由 KV 缓存的读取带宽决定，驱逐与重算反而可能增加预填开销。论文材料明确指出未涉及 KV 缓存策略，也未给出长上下文与仓库级场景下的 KV 缓存能耗分析——这是一个明确的空白：在 Blackwell 这类显存带宽受限的平台上，KV 缓存的驻留位置与复用方式直接决定解码能耗，而这部分账在论文的框架里还没有被打开。</p>\n<p>具体例子：一个工具调用循环里，模型反复读同一份仓库上下文、生成小段补丁、跑测试、再读上下文。预填在每一轮都可能重复发生（如果前缀未被复用），解码则每轮只产出少量 token。旧方案会把这类负载当作普通批处理请求，用统一的 max_tokens 与批大小处理；结果是预填开销被重复支付，解码开销被固定上限放大。论文的策略只能压缩解码那部分，预填的重复支付需要靠前缀复用与 KV 缓存管理来解决——这正是它留给后续工程的部分。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-6\">六 · 非改不可的工程判断：能效必须落到解码策略上</h3>\n<p>把上述账本合起来看，旧方案的非改不可之处在于：它们优化的是“单位时间做多少事”，而代码生成服务真正要优化的是“每个通过测试的请求花多少电”。这两个目标在长上下文、短输出、验证驱动的代码任务上并不一致。模型侧缩放会牺牲通过率，批调度会掩盖生成长度的浪费，KV 缓存管理只动显存不动带宽账。论文的选择是把优化变量下沉到解码策略：让模型自己决定生成多长，并用通过率约束把质量锁住。</p>\n<p>这个选择的工程代价也很清楚：策略需要训练信号（测试用例），需要分阶段能耗度量（预填与解码分开记），需要在置信度与通过率之间做校准。它不解决预填的重复支付，也不解决 KV 缓存的带宽账，更不涉及量化与分离式预填/解码。但它是第一个把“生成多少”当作可优化量的框架，而在这个框架之上，Blackwell 侧的 NVFP4/FP8 量化、KV 缓存复用与分离式预填才能被组合进来放大收益——前提是硬件档位与能耗测量方法被补齐，否则跨平台的能耗结论无法比较。对做容量规划的工程师来说，这意味着一个具体的动作：在把这类策略上线之前，先在自己的硬件上把预填与解码的能耗分开测出来，否则你不知道省下的到底是哪一笔账。</p>\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-7\">七 · 负载形态的三个可测维度：输入长度、并发与批大小</h3>\n<p>GREEN-CODE 的能耗目标写在解码策略上，但策略面对的不是抽象分布，而是一组具体请求。对代码生成而言，请求形态至少由三个维度刻画：输入长度（问题描述加上下文，仓库级补全时可达数万 token）、并发到达率、以及服务端实际聚合出的批大小。材料明确未给出这三者的分布，因此本部分不引用任何数值，而是给出可核查的测量口径，让读者在自有部署上把这三项量出来，再判断策略是否值得启用。</p>\n<p>测量口径上，输入长度应按 tokenizer 后的真实 token 数统计，分别记录预填 token 数 $L_p$ 与解码 token 数 $L_d$，而不是按字符数或按“问题条数”计数——后者在仓库级上下文下会严重低估预填开销。并发应记录到达过程而非平均值：至少采集每秒到达数的时间序列与并发驻留数（in-flight requests）的分布，因为批调度器看到的是瞬时驻留，而不是小时均值。批大小则要区分“逻辑批”（一次调度纳入的请求数）与“物理批”（一次前向实际拼进的 token 数），两者在连续批处理下并不相等。</p>\n<p>这三项直接决定能耗结构。预填阶段的计算量随 $L_p$ 线性增长且高度并行，是算力密集；解码阶段每步只处理一个 token，却要反复读整个 KV 缓存，是带宽密集。用可核查的粗粒度模型表达：单请求解码能耗近似正比于</p>\n<div class=\"formula\">$$\\mathcal{E}_{\\text{dec}} \\approx L_d \\cdot \\left( W_{\\text{model}} + 2 \\cdot n_{\\text{layer}} \\cdot d_{\\text{head}} \\cdot L_{p} \\cdot b_{\\text{bytes}} \\right)$$</div>\n<p>其中括号内第一项是权重读取，第二项是 KV 缓存读取，$b_{\\text{bytes}}$ 是每元素字节数。这个式子说明：在长上下文下，KV 读取项会压过权重项，于是“少生成 token”与“复用 KV”成为两个独立的节能杠杆。GREEN-CODE 只动了 $L_d$，而 $L_p$ 侧的能耗要靠 KV 缓存管理去压——这正是该文未覆盖、但部署时必须补上的部分。</p>\n<p>具体例子：仓库级补全请求的 $L_p$ 远大于 $L_d$，若按请求数计费会得出“解码主导”的错误结论；按 token 计费则显示预填占能耗大头，此时提前终止解码带来的节省被稀释，而前缀缓存命中率的提升才是主收益。反过来，短问题、长生成的场景（如从一句描述生成完整脚本）中 $L_d$ 主导，GREEN-CODE 的长度调节策略才有明显杠杆。判断顺序应是先量 $L_p/L_d$ 比值，再决定优化重心。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-8\">八 · SLO 与长尾：能耗优化的可行域由尾延迟划定</h3>\n<p>能耗最小化不是无约束的。服务端同时受首 token 延迟（TTFT）与每 token 间隔（TPOT）约束，而这两者对预填与解码的敏感度不同：TTFT 由预填长度与排队深度决定，TPOT 由解码步的带宽占用与批内竞争决定。GREEN-CODE 的目标函数只写了通过率约束 $\\tau$，没有写延迟约束，这在离线批处理场景成立，在在线服务场景则不成立。工程上应把可行域写成</p>\n<div class=\"formula\">$$\\min_{\\pi}\\ \\mathbb{E}[\\mathcal{E}(\\pi,x)] \\quad \\text{s.t.}\\quad P(\\text{pass})\\ge\\tau,\\ \\ P(\\text{TTFT}\\le T_1)\\ge q_1,\\ \\ P(\\text{TPOT}\\le T_2)\\ge q_2$$</div>\n<p>分位数 $q_1,q_2$ 的选择决定了长尾能吃掉多少节能空间。长尾的来源在代码生成里很具体：少数请求上下文极长（整个仓库文件被拼入），少数请求生成极长（模型陷入反复修补的循环），以及测试用例校验本身耗时波动。前两类会同时拉高预填与解码能耗，并挤占同批其他请求的 TPOT——因为连续批处理中一个长解码请求会持续占用批槽位，抬高整批的每步时间。</p>\n<p>可核查的测量口径：按请求记录 TTFT、TPOT 的完整分布而非均值，至少给出 p50/p90/p99；同时记录每个请求的 $L_p$、$L_d$ 与批内共驻请求数，用以归因长尾是来自输入长度、生成长度还是调度排队。若 p99 的 TPOT 超限主要来自长解码请求，则 GREEN-CODE 式的提前终止不仅省能耗，还改善尾延迟——这是双重收益；若长尾来自预填，则策略无用，需转向分块预填或预填/解码分离。</p>\n<p>具体例子：一个工具调用循环中的代码生成请求，模型在置信度不足时反复生成候选片段，$L_d$ 被拉长，单请求能耗上升且占用批槽位，导致同批短请求的 TPOT 被拖慢。此时若策略能在置信度高时终止，既降低该请求能耗，又释放批容量——但前提是终止不损害通过率，而这只能靠测试用例反馈来标定，正是该文策略学习环节的输入。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-9\">九 · 负载塑造方案：批大小如何改变能耗最优解</h3>\n<p>批大小不是中立的调度参数，它改变能耗的构成比例，从而改变策略的最优解。设批内有 $B$ 个请求同时解码，权重读取在批内被摊薄一次，KV 读取则随 $B$ 线性增长（每请求各自的缓存）。于是每 token 的边际能耗近似为</p>\n<div class=\"formula\">$$\\mathcal{E}_{\\text{step}}(B) \\approx W_{\\text{model}} + B \\cdot 2 n_{\\text{layer}} d_{\\text{head}} L_p b_{\\text{bytes}}$$</div>\n<p>小批时权重项主导，节能要靠减少解码步数，即 GREEN-CODE 的长度调节；大批且长上下文时 KV 项主导，节能要靠提高缓存命中与压缩缓存，长度调节的边际收益下降。这意味着同一策略在不同批大小下的性价比不同，部署时必须按实际批分布评估，而不能把离线单请求实验的结论直接搬到在线服务。</p>\n<p>测量口径：记录每个解码步的实际批内 token 数与驻留请求数，计算“每请求每 token 能耗”随 $B$ 的变化曲线；同时记录批内请求的 $L_p$ 方差——方差大时，长上下文请求会主导整批的 KV 读取，短请求被“搭便车”式地拖慢。可核查的做法是按 $B$ 分桶统计能耗与 TPOT，而不是给一个全局均值。</p>\n<p>具体例子：在固定并发下把批大小从保守值提高，吞吐上升但每请求 TPOT 恶化；若此时 GREEN-CODE 策略把部分请求的解码长度砍短，批槽位周转加快，吞吐与能耗同时改善。反之若批已很大且上下文很长，砍长度省下的 KV 读取有限，收益被权重项摊薄稀释。工程判断是：先测 $B$ 与 $L_p$ 的联合分布，再决定把预算投给长度策略还是缓存策略。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-10\">十 · 方案反过来限制负载：策略如何改变请求形态</h3>\n<p>能耗策略不是被动适应负载，它会反向塑造负载。GREEN-CODE 在置信度高时提前终止生成，直接改变的是 $L_d$ 的分布：长尾被截短，均值下降，但代价是部分请求的通过率可能下滑。若策略被部署为服务端默认行为，客户端会观察到更快的返回与更短的输出，进而改变调用模式——例如更频繁地发起小请求、或在失败后重试，后者会把被截短的请求重新送回，形成“终止—失败—重试”的循环，反而抬高总能耗。</p>\n<p>可核查的测量口径必须把重试计入：统计每个逻辑任务的总请求数（含重试）、总 token 数与总能耗，而不是按单次请求计。若策略使单次请求能耗下降但重试率上升，净能耗可能不降。这与该文以测试用例通过率作为约束的设计直接相关：约束 $\\tau$ 若设得过松，重试成本会吃掉节能；设得过紧，策略退化为不终止，节能消失。</p>\n<p>具体例子：代码补全场景缺少测试用例，无法判定截短后的代码是否正确，用户往往直接采纳或手动修补，修补过程产生的额外请求不在能耗统计内。这说明该文的反馈信号在无测试用例场景下不可用（材料已指出此局限），部署时若强行套用，会把“未验证的节能”误记为收益。工程上应把校验开销与重试开销纳入能耗口径，否则策略的账面收益与真实收益背离。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-11\">十一 · 可核查的测量清单与 Blackwell 上的落地口径</h3>\n<p>把上述维度落成一张可执行的测量清单，是本部分对部署者的直接交付。清单应包含：每请求的 $L_p$、$L_d$、TTFT、TPOT、批内共驻数、是否重试、是否通过校验；按 $L_p$ 与 $B$ 分桶的能耗曲线；预填与解码能耗的分离统计。材料明确指出该文能耗度量覆盖预填与解码两阶段但未给出硬件档位与测量方法，因此跨平台可比性受限——这正是清单要补的：在 Blackwell 上，能耗应按 GPU 板卡功率积分（或按机架功率在 GB200 NVL72 层面分摊）与 token 计数联合给出，并注明数值精度档位，因为 NVFP4/FP8 下权重与 KV 的字节数 $b_{\\text{bytes}}$ 改变，直接改变上面公式中两项的相对权重。</p>\n<p>具体到硬件档位：SM100/SM103 上 tcgen05 与 TMEM 的引入使 MMA 吞吐提升，预填阶段更偏向算力饱和，解码阶段仍受 KV 带宽约束。因此测量时必须分别报告预填与解码的能耗占比，否则无法判断该把优化预算投向量化（压 $b_{\\text{bytes}}$）还是投向长度策略（压 $L_d$）。分离式预填/解码会进一步改变这一比例：预填节点算力密集、解码节点带宽密集，能耗要在两侧分别计量再合并，单机口径不适用。</p>\n<p>工程判断落在最后一步：GREEN-CODE 的长度调节策略是一个低门槛、可叠加的杠杆，但它只在 $L_d$ 主导且通过率可验证的场景中兑现；在长上下文仓库级补全中，$L_p$ 与 KV 读取主导，必须先做前缀缓存与缓存压缩，再谈长度策略。测量清单的作用是让这个判断有据可依，而不是靠策略名称或论文结论直接下注。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-12\">十二 · 当“提前停”遇上真实负载：策略的适用边界与测量口径</h3>\n<p>GREEN-CODE 的策略只在解码阶段调节生成长度，因此它的收益上限完全由请求形态决定。设单请求预填能耗为 <span class=\"formula\">$$E_{\\text{pre}}(L_{\\text{in}})$$</span>、解码能耗为 <span class=\"formula\">$$E_{\\text{dec}}(L_{\\text{out}})$$</span>，策略能压缩的只有后者；当 <span class=\"formula\">$$L_{\\text{in}}\\gg L_{\\text{out}}$$</span>（仓库级补全、长文件上下文、工具调用回填的大段日志）时，预填占比压倒解码，提前终止带来的节省被稀释到可忽略。反之在短问题、长生成（竞赛题、从零写模块）的形态下，解码占主导，策略才有发挥空间。这意味着部署前必须先测输入/输出长度分布，而不是把策略当作通用节能开关。</p>\n<p>第二个边界是校验开销与并发结构。策略的反馈信号来自运行测试用例，而测试执行本身消耗 CPU 时间与调度槽位；在连续批处理下，一个请求提前终止只释放其占用的解码步，batch 内其他请求仍按最长序列推进，实际吞吐增益取决于同批请求的长度方差——方差小则早停几乎不改变 batch 完成时间。可用一个粗略判据：若同批请求生成长度的变异系数低于约 0.2，早停对吞吐的边际贡献迅速衰减，此时应优先调整批大小与并发上限，而非细化解码策略。</p>\n<p>第三个边界是无测试用例场景。代码补全、内联建议这类请求没有可执行的验证入口，通过率约束 <span class=\"formula\">$$\\mathbb{1}\\{\\text{pass}\\}$$</span> 无法计算，策略退化为无约束的长度压缩，正确性风险不可控。工程上应把该策略限定在“有测试可跑”的离线批处理或 CI 辅助场景，补全路径改用置信度阈值加固定长度上限的保守配置。</p>\n<p>测量口径必须可核查：按请求记录 <span class=\"formula\">$$L_{\\text{in}}, L_{\\text{out}}$$</span>、预填与解码的分段耗时、batch 内并发数、GPU 能耗采样窗口，并按长度分桶报告通过率与单位通过请求能耗，而非只报全局均值——长尾请求（超长上下文、反复重试）往往主导总能耗，均值会掩盖策略在尾部的失效。</p>\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-13\">十三 · 从能耗目标反推 kernel 选择</h3>\n<p>GREEN-CODE 的优化变量落在解码阶段的生成长度与策略选择上，能耗度量覆盖预填与解码两阶段。把这一目标映射到 Blackwell 硬件，第一件事不是选量化格式，而是判断能耗被谁支配。预填阶段是计算密集的 GEMM，能耗近似正比于 <span class=\"formula\">$$E_{\\text{prefill}} \\approx P_{\\text{SM}} \\cdot t_{\\text{prefill}},\\quad t_{\\text{prefill}} \\approx \\frac{2 \\cdot N_{\\text{ctx}} \\cdot d_{\\text{model}}^2}{F_{\\text{eff}}}$$</span> 其中 $N_{\\text{ctx}}$ 为上下文 token 数、$d_{\\text{model}}$ 为隐藏维、$F_{\\text{eff}}$ 为有效算力。解码阶段则是访存受限，每生成一个 token 要把权重与 KV 缓存读一遍，能耗近似正比于搬运字节数而非浮点运算数。这两条曲线的交叉点决定了：对长上下文仓库级补全，预填能耗占比高，压缩 $N_{\\text{ctx}}$ 或提高 Tensor Core 利用率收益最大；对工具调用循环中的短解码，权重搬运能耗占主导，量化权重位宽直接决定能耗下限。GREEN-CODE 的策略在置信度高时提前终止生成，本质上是砍掉解码阶段的 token 数，从而线性削减这部分搬运能耗——但前提是单 token 的解码能耗已经被压到较低水平，否则提前终止省下的只是被浪费的那部分。</p>\n<p>工程判断：在 B200 上，一个 70B 级模型 BF16 解码单 token 需搬运约 140 GB 权重，若 HBM 带宽按代际量级估算，单 token 时间落在数十毫秒量级，能耗以焦耳计；换成 FP8 权重后搬运量减半，NVFP4 再减半。这就是为什么 GREEN-CODE 的“少生成 token”策略必须与低精度权重叠加才有意义：策略省的是 token 计数，量化省的是每 token 的字节数，两者相乘才是总能耗的下降。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-14\">十四 · 四种数值格式的误差结构与适用位置</h3>\n<p>FP16 与 BF16 在 Blackwell 上都是 16 位存储，差别在指数位与尾数位分配：FP16 尾数多、动态范围窄，BF16 动态范围与 FP32 同阶但尾数少。代码生成任务的激活值分布跨层差异大，BF16 因动态范围宽而更不容易溢出，是预填 GEMM 与 KV 缓存的稳妥默认。FP8 分 E4M3 与 E5M2 两支，前者精度优先用于权重与激活，后者范围优先用于梯度类场景；推理侧主要用 E4M3。NVFP4 是 Blackwell 引入的 4 位块浮点格式，每 16 个元素共享一个缩放因子，尾数实际只有 3 位有效位，必须靠块内缩放把动态范围拉回来。</p>\n<table class=\"mini\"><thead><tr><th>格式</th><th>位宽</th><th>误差来源</th><th>推理中的典型位置</th></tr></thead><tbody><tr><td>BF16</td><td>16</td><td>尾数截断，相对误差小</td><td>预填 GEMM、KV 缓存、注意力</td></tr><tr><td>FP16</td><td>16</td><td>动态范围窄，易溢出</td><td>激活值范围已知的层</td></tr><tr><td>FP8 E4M3</td><td>8</td><td>尾数仅 3 位，量化步长大</td><td>权重、线性层输入</td></tr><tr><td>NVFP4</td><td>4</td><td>块缩放残差 + 3 位尾数</td><td>权重为主，激活需校准</td></tr></tbody></table>\n<p>误差传播的关键在累加精度。以 FP8 GEMM 为例，输入被量化到 8 位，但 Tensor Core 内部的乘加累加器保持 FP32（或按指令选择更高精度），单次点积的相对误差由输入量化主导而非累加主导。写成逐项形式：<span class=\"formula\">$$\\hat{y}=\\sum_{i=1}^{K} \\hat{a}_i \\hat{b}_i,\\quad \\hat{a}_i=a_i(1+\\delta_a),\\ \\hat{b}_i=b_i(1+\\delta_b),\\quad \\frac{|\\hat{y}-y|}{|y|}\\lesssim \\max(|\\delta_a|,|\\delta_b|)+\\frac{\\sqrt{K}\\,\\epsilon_{\\text{acc}}}{\\sqrt{K}}$$</span> 第一项是输入量化误差，第二项是累加舍入，$K$ 为归约长度。对 $K$ 很大的线性层，输入量化误差不会随 $K$ 放大，但若累加器被降到 FP16，第二项会随 $\\sqrt{K}$ 增长并在长归约上压过第一项。这就是“累加精度不能省”的定量理由：省累加精度的收益是寄存器与带宽，代价是误差随归约长度恶化，在 $d_{\\text{model}}$ 较大的层上尤其明显。</p>\n<p>具体例子：一个 $K=8192$ 的 FFN 中间层，若用 FP8 输入、FP32 累加，误差量级由 E4M3 的 3 位尾数决定；若把累加降到 FP16，累加项的相对误差随归约长度累积，在代码生成这种对数值敏感的 logits 分布上会放大低概率 token 的排序抖动，进而影响采样决策与生成长度——恰好是 GREEN-CODE 策略所依赖的信号。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-15\">十五 · tcgen05、TMEM 与 2-SM MMA 的代价结构</h3>\n<p>Blackwell 第五代 Tensor Core 的编程接口是 tcgen05 指令族，配套 TMEM（Tensor Memory）作为矩阵乘的累加器与操作数暂存。与 Hopper 的 wgmma 相比，tcgen05 把累加器从寄存器堆挪到专用片上存储，寄存器压力下降，但引入 TMEM 的分配与同步开销。2-SM MMA 让一对 SM 协同完成一次更大的矩阵乘，把单次 MMA 的 M 维或 N 维扩大，减少指令发射次数与数据复用距离。伪代码思路：</p>\n<ul>\n<li>分配 TMEM 块，将 A 操作数从 SMEM 载入，B 操作数按 2-SM 对分片；</li>\n<li>发射 tcgen05 MMA，累加结果留在 TMEM，不落寄存器；</li>\n<li>在 epilogue 中从 TMEM 读回累加结果，做缩放与量化后写回；</li>\n<li>若走 NVFP4，缩放因子在 epilogue 中按块应用，避免中间结果反复量化。</li>\n</ul>\n<p>代价结构：TMEM 容量有限，一个 CTA 能驻留的累加块数受限于 TMEM 分区，这直接约束 tile 尺寸选择；2-SM MMA 要求两个 SM 的 tile 形状匹配，调度不齐时会出现一个 SM 等待另一个的空转，吞吐下降。对推理而言，预填阶段的大 GEMM 能从 2-SM MMA 拿到接近线性的吞吐提升，但解码阶段的 skinny GEMM（batch 很小、N 维小）难以填满 2-SM 的 tile，收益转为负——空转的 SM 仍在耗电。这是 GREEN-CODE 场景下的关键判断：解码路径应优先用小 tile、单 SM 的 kernel，把 2-SM MMA 留给预填与批量较大的连续批处理场景。</p>\n<p>具体例子：仓库级代码补全的预填上下文可达数万 token，此时预填 GEMM 的 M 维很大，2-SM MMA 的 tile 利用率高，单次 MMA 覆盖的计算量翻倍，指令开销摊薄；而工具调用循环中的解码 batch 常为个位数，此时应退回单 SM 路径并用 NVFP4 权重压缩搬运量，而不是强行套用 2-SM 形状。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-16\">十六 · 量化与 KV 缓存的耦合代价</h3>\n<p>KV 缓存是解码阶段除权重之外的第二大搬运对象。把 KV 缓存量化到 FP8 可将每 token 的缓存读取字节减半，但注意力计算的 softmax 对 KV 量化误差敏感：键向量的量化误差进入点积后改变注意力权重分布，值向量的量化误差直接叠加到输出。误差形式化：<span class=\"formula\">$$\\tilde{o}=\\sum_j \\text{softmax}_j\\!\\left(\\frac{q\\cdot \\tilde{k}_j}{\\sqrt{d}}\\right)\\tilde{v}_j,\\quad \\tilde{k}_j=k_j+\\eta_j,\\ \\tilde{v}_j=v_j+\\xi_j$$</span> 键误差 $\\eta_j$ 通过 softmax 的非线性被放大到权重上，值误差 $\\xi_j$ 线性进入输出。工程上通常对键保留更高精度或做 per-channel 缩放，对值用量化，因为 softmax 的指数运算对键误差更敏感。</p>\n<p>代价：KV 缓存量化省下的是 HBM 带宽与容量，换来的是注意力输出的数值抖动。对 GREEN-CODE 的策略学习，这种抖动会传导到 token 置信度——策略依据置信度决定是否提前终止，若量化使置信度估计偏移，提前终止的判定就会失准，可能提前截断导致通过率下降，触发约束项 $\\mathbb{1}\\{\\text{pass}\\}\\ge\\tau$ 失效。因此量化方案必须与策略的置信度阈值联合校准，而不是各自独立调参。具体例子：长上下文补全中 KV 缓存占用可达数十 GB，FP8 量化后容量减半，允许更大的批或更长的上下文驻留，但需在策略侧重新标定终止阈值，否则省下的能耗会被通过率回退抵消。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-17\">十七 · 精度档位与能耗度量的可复现性</h3>\n<p>GREEN-CODE 的材料未给出硬件档位、数值精度与能耗测量方法，这直接导致其能耗结论跨平台不可比。在 Blackwell 上做能效优化，必须把精度档位作为一等公民记录：同一模型在 BF16、FP8、NVFP4 三档下的单 token 能耗差异来自权重搬运字节数与 Tensor Core 吞吐两条曲线，混在一起报告会掩盖真实收益来源。度量上应分离预填与解码：预填能耗用 GEMM 吞吐与 SM 功耗估算，解码能耗用 HBM 搬运字节与带宽功耗估算，两者相加才是单请求能耗。公式上，单请求能耗可写成 <span class=\"formula\">$$E_{\\text{req}}=E_{\\text{prefill}}(N_{\\text{ctx}},F_{\\text{eff}},P_{\\text{SM}})+\\sum_{t=1}^{T}E_{\\text{decode}}(t)$$</span> 其中 $T$ 是策略决定的生成长度。GREEN-CODE 的策略作用于 $T$，量化作用于 $E_{\\text{decode}}$ 的每项系数，两者正交但相乘。</p>\n<p>工程判断：在没有统一能耗测量口径的情况下，任何“能效提升百分比”都不可跨平台比较。部署侧应固定精度档位与批配置后再报告能耗，并把预填/解码拆分作为强制字段。对 B200/B300 与 GB200 NVL72，NVLink 5 域内的权重与 KV 搬运不走 HBM，分离式预填/解码拓扑会改变能耗归属，度量时必须标注数据路径，否则预填节点的能耗会被错误地记到解码节点上。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-18\">十八 · 把精度决策嵌进策略循环</h3>\n<p>GREEN-CODE 的策略学习以通过率为约束、能耗为目标，训练信号来自测试用例与能耗度量。若把精度档位作为策略的一个动作维度，策略就不只决定“生成多长”，还决定“用哪档精度解码”。这要求能耗反馈信号携带精度标签，否则策略无法区分“少生成 token 省下的能耗”与“低精度搬运省下的能耗”。伪代码思路：在每个解码步，策略根据当前置信度与已生成长度选择继续/终止；同时在请求级选择精度档位，高置信度请求走 NVFP4 权重 + FP8 KV，低置信度或长上下文请求回退到 BF16 以保证通过率。代价是精度切换带来 kernel 重编译或预编译多档 kernel 的显存开销，以及切换点的流水线气泡。</p>\n<p>具体例子：一道需要长上下文检索的仓库级补全题，预填阶段用 BF16 保证注意力数值稳定，解码阶段权重走 NVFP4、KV 走 FP8，策略在连续若干 token 置信度高于阈值时终止；测试用例校验通过后，能耗记录同时标注预填精度与解码精度，反馈给策略更新。这样精度档位与生成长度两个变量在同一约束下被联合优化，而不是先定量化再谈策略——后者会把量化带来的通过率回退误记为策略失效。最后落在工程判断上：Blackwell 的 tcgen05 与 NVFP4 把单 token 能耗下限压低了一个档位，GREEN-CODE 的长度策略才有放大的空间；反过来，若精度档位不记录，能耗度量就失去可复现性，策略学到的只是特定硬件配置下的偶然最优。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-19\">十九 · 能效策略在数值精度与 Blackwell 算子栈上的失效边界</h3>\n<p>该方案的能耗度量只统计预填与解码两阶段，但材料未给出数值精度档位，这直接决定了能耗结论能否迁移到 Blackwell。策略在解码阶段依据置信度提前终止，其收益以 token 数为单位计量；而真实能耗由 kernel 的实际数据通路决定：同一 token 数在 BF16 下走第五代 Tensor Core 的 FP16/BF16 通路，在 FP8 下走块缩放通路，在 NVFP4 下走更窄的乘加阵列，单 token 的能耗与显存带宽占用并不等价。若策略学到的“少生成”在 NVFP4 上带来的边际能耗下降远小于在 BF16 上，则质量约束 τ 下的最优策略会随精度档位漂移，跨平台复现时不可比。</p>\n<p>累加精度是第二个失效点。tcgen05 MMA 将累加器置于 TMEM，2-SM MMA 让两个 SM 共享一次更大的矩阵乘，单次发射覆盖的 K 维更长；此时若策略提前终止导致解码步的 M 维（批内 token 数）变小，2-SM 配对的收益被摊薄，kernel 进入低利用率区间，能耗/Token 反而上升。用式子表达单步代价：</p>\n<div class=\"formula\">$$E_{\\text{step}} \\approx \\frac{P_{\\text{idle}}\\cdot t_{\\text{launch}} + P_{\\text{mma}}\\cdot \\frac{2 M N K}{r_{\\text{peak}}}}{M}$$</div>\n<p>其中 M 为有效批内行数，r_peak 为该精度档位的峰值算力，P_idle 与 P_mma 分别为发射开销与阵列功耗。M 缩小时分母变小、固定项被放大，这正是“提前终止省能耗”在 Blackwell 上可能反转为增耗的条件：只有当省下的 token 数足以抵消 kernel 利用率下降带来的固定开销摊薄损失时，策略才真正省能。</p>\n<p>第三个边界是策略反馈信号与精度误差的耦合。NVFP4/FP8 的量化误差会改变生成代码的通过标志，而通过率是约束项的唯一来源；材料未给出量化方案，因此无法判断 τ 是在何种数值条件下标定的。若在 BF16 下标定 τ，迁移到 NVFP4 后通过率下降会使约束被违反，策略被迫延长生成长度，能耗收益被抵消。工程判断是：把精度档位作为策略状态的一部分显式建模，并在能耗度量中记录 kernel 档位与累加精度，否则该方案的能效结论只在单一未标明的数值配置下成立。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>策略收益方向</th><th>系统代价</th></tr></thead><tbody><tr><td>BF16 + 大 M</td><td>提前终止省 token 即省能</td><td>KV 缓存带宽占用高</td></tr><tr><td>NVFP4 + 小 M</td><td>收益被固定开销摊薄</td><td>2-SM 配对利用率下降</td></tr><tr><td>无测试用例</td><td>约束项缺失，策略不可用</td><td>无法标定 τ</td></tr></tbody></table>\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-20\">二十 · 显存账本的三层结构与可复算预算</h3>\n<p>在 Blackwell 上做代码生成推理，显存不是一块整账，而是三本互相挤压的账：权重、激活、KV cache。权重是静态的，按精度档位一次性买断；激活是每层前向的临时工作区，随批大小与序列长度线性走；KV cache 是随解码步数单调增长的动态账，也是长上下文仓库级补全里最先爆掉的那一本。三者共享同一块 HBM3e，任何一本超支都会把另外两本挤到换出或重算。</p>\n<p>给出可复算的预算式。设参数量 $P$、权重每元素字节 $b_w$、层数 $L$、隐藏维 $d$、KV 头数 $h_{kv}$、头维 $d_h$、每元素字节 $b_{kv}$、批大小 $B$、上下文长度 $S$，则：</p>\n<div class=\"formula\">$$M_{\\text{weight}} = P \\cdot b_w,\\qquad M_{\\text{KV}} = 2 \\cdot L \\cdot h_{kv} \\cdot d_h \\cdot b_{kv} \\cdot B \\cdot S$$</div>\n<p>系数 2 来自 K 与 V 两份。激活项在推理时被 chunked prefill 切成固定工作区，通常按最大 micro-batch 的 token 数乘以每 token 激活字节估算，不随总序列线性增长，这是它能被预算住的原因。以 FP8 权重（$b_w=1$）、FP8 KV（$b_{kv}=1$）、$L=80$、$h_{kv}=8$、$d_h=128$ 的稠密档位为例，每 token 每层的 KV 是 $2\\times8\\times128=2048$ 字节，全层即约 160 KiB/token；当 $B=32$、$S=32768$ 时，KV 账本约 160 GiB 量级，已经压过多数单卡容量，必须靠分页、压缩或卸载把这一本压回去。这个算式不依赖任何实测数字，读者代入自己模型的 $L$、$h_{kv}$、$d_h$ 即可复算，这也是本部分要求“可复算”的落点。</p>\n<p>工程代价直接体现在这里：KV 账本每翻一倍，可容纳的并发请求数就减半，解码阶段的批调度空间被压缩，吞吐随之下降；反过来，为了保住并发而缩小 $S$，仓库级补全的跨文件上下文就被截断，通过率受损。GREEN-CODE 的能耗度量覆盖预填与解码两阶段，但材料未给出上下文长度分布，因此这套账本无法从论文直接读出，只能由部署方按自己的请求形态填参。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-21\">二十一 · 分页与块表：把 KV 从连续数组变成可回收的页</h3>\n<p>连续分配 KV 的问题是内部碎片：按最大长度预留，短请求浪费；按实际长度追加，长请求触发重分配与拷贝。分页把 KV 切成固定 token 数的块（block），每块独立分配物理页，逻辑序列由块表（block table）索引。解码时注意力核按块表 gather，块满即封存，块空即回收到空闲池，跨请求共享前缀时同一物理块可被多个块表引用并加引用计数。</p>\n<p>伪代码思路：序列追加 token 时查当前块剩余槽位，满则从空闲池取新块并写入块表；序列结束或请求被抢占时按块表逐块减引用计数，归零则归还。抢占（preemption）在显存不足时把低优先级序列的块换出到主机内存或直接丢弃重算，这是连续批处理在显存压力下的必要动作。</p>\n<p>代价落在三处：块表查表带来间接寻址，注意力核的地址计算比连续布局多一层；块大小是碎片与查表开销的折中，块越小碎片越少但表越长；换出与换入走 PCIe，带宽远低于 NVLink 5，一次抢占的恢复延迟足以吃掉若干解码步的收益。对代码生成而言，仓库级补全的提示前缀高度重复（同一仓库的同一批文件被反复引用），前缀共享能把 KV 账本按共享比例直接折掉，这是分页在代码场景里最值钱的一招；但 GREEN-CODE 的材料未描述长上下文复用机制，这一收益在其框架内未被度量。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-22\">二十二 · 压缩与复用：量化 KV、结构裁剪、前缀缓存</h3>\n<p>KV 压缩有三条互不排斥的路。其一是数值压缩：KV 按 FP8 或 NVFP4 存储，$b_{kv}$ 从 2 降到 1 甚至 0.5，账本按比例缩小，代价是注意力打分的数值误差，长上下文下误差累积更明显，需要 per-block 缩放因子把动态范围压住。其二是结构裁剪：按头、按层、按 token 丢弃低贡献的 KV，或对 token 做合并，本质是用通过率换容量。其三是复用：前缀缓存把相同提示的 KV 块跨请求保留，命中即跳过预填。</p>\n<p>复用对能耗的意义要单独算。预填的计算量与 $S$ 成正比且高度并行，是算力密集；解码每步只处理一个 token 却要读完整 KV，是带宽密集。前缀命中省掉的是预填那一段算力，而 KV 账本本身并未减少——块仍在显存里占着。因此复用降低的是预填能耗与首 token 延迟，不降低稳态解码的带宽压力。GREEN-CODE 的策略在解码阶段调节生成长度，属于减少解码步数；若与前缀复用叠加，两者削减的是能耗结构里不同的两段，材料未给出二者的联合度量，部署方需要分别打点。</p>\n<p>代价判断：KV 量化到 FP8 通常被视为近无损档位，但代码生成对标识符与数字的精确性敏感，量化误差若落在注意力打分上会改变 token 选择，通过率约束 $\\tau$ 是否仍被满足需要逐档验证；结构裁剪的激进程度直接对应通过率下降，属于用质量换显存，与 GREEN-CODE 的质量约束目标同向但机制不同。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-23\">二十三 · 卸载与带宽瓶颈的位置</h3>\n<p>卸载把冷 KV 页放到主机内存甚至 NVMe，热页留在 HBM。判断是否值得卸载，只看一个比值：被卸载数据每步被读回的字节数乘以解码步数，与 PCIe 有效带宽之比，是否小于把它留在 HBM 所挤掉的并发损失。解码阶段每生成一个 token 要读一遍参与注意力的全部 KV，$B$ 条序列、$S$ 长度、每 token $2 L h_{kv} d_h b_{kv}$ 字节，这个读放大是解码带宽瓶颈的根源：算力几乎闲置，HBM 带宽被打满。</p>\n<div class=\"formula\">$$\\text{ArithmeticIntensity}_{\\text{decode}} \\approx \\frac{2P}{2 L h_{kv} d_h b_{kv} \\cdot S} \\ \\text{FLOP/Byte}$$</div>\n<p>分母随 $S$ 线性增长，分子是权重一次读入的算力，所以上下文越长，解码越偏向带宽受限，卸载回读的代价也越难被算力掩盖。Blackwell 的 HBM3e 容量与带宽提升缓解的是分子侧的等待，但没有改变这个比值随 $S$ 恶化的趋势。工程判断因此很直接：卸载适合冷前缀与低优先级长序列，不适合正在活跃解码的热序列；一旦热序列被换出，每一步都要付 PCIe 往返，延迟抖动会直接破坏 SLO。</p>\n<p>具体例子：一条 32K 上下文的仓库级补全请求，其 KV 账本按第一节算式在百 GiB 量级，单卡放不下，若整条卸载则每步回读量巨大，解码吞吐塌陷；可行做法是把共享前缀块常驻 HBM（多请求引用摊薄成本），把各请求独有的尾部块留在 HBM，仅把已封存且短期不再命中的历史块下沉。这与分页的引用计数机制天然配合。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-24\">二十四 · 把账本接回能耗目标</h3>\n<p>GREEN-CODE 的优化目标是质量约束下的期望能耗最小化，优化变量落在解码阶段的生成长度与策略选择上。显存账本与这个目标的关系是间接但确定的：KV 账本决定可并发数 $B$，$B$ 决定单位时间吞吐，吞吐决定摊到每个通过样本上的固定能耗（权重读入、预填、调度开销）。生成长度策略削减的是解码步数，即分子侧的重复读；分页与压缩削减的是分母侧的驻留压力。两者作用在不同项上，不能互相替代。</p>\n<p>因此容量规划的落地顺序是：先用第一节算式按目标 $B$ 与 $S$ 算出 KV 账本，与权重账本相加得到单卡驻留下限；若超限，先试前缀共享与 KV 量化，再试结构裁剪，最后才动卸载，因为前三者不引入 PCIe 往返。每动一档都要用通过率约束 $\\tau$ 复核，因为压缩与裁剪都可能改变 token 选择。材料未给出硬件档位与能耗测量方法，这套顺序只能作为工程判断而非论文结论；论文明确指出的局限正是长上下文与仓库级场景下缺少 KV 缓存能耗分析，容量规划缺少依据——本节的算式就是把这个缺口补成可填参的形式。</p>\n<p>最后落在机制上：解码阶段的带宽瓶颈由每步 KV 读放大决定，而读放大的分母就是 KV 账本本身。任何降低账本的机制（分页共享、量化、裁剪、卸载）都在改变分母，任何降低步数的机制（提前终止、投机解码的接受长度）都在改变乘数。GREEN-CODE 只动了乘数，分母留给了部署方；在 Blackwell 上把两者接起来，才是能效收益真正放大的位置。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-25\">二十五 · 提前终止策略在显存账本上的边界：省的是解码算力，不是 KV 驻留</h3>\n<p>GREEN-CODE 的策略变量落在解码阶段的生成长度上：置信度高时提前终止，不确定时继续生成。这一机制直接削减的是解码步数与随之产生的激活与权重带宽流量，但它并不削减预填阶段已经建立的 KV 缓存驻留量。对 Blackwell 部署而言，这是一个必须算清的账：一个仓库级补全请求的上下文可能远长于最终生成的代码补全片段，预填完成后 KV 已按上下文长度全额占用 HBM3e，提前终止只让这块缓存提前若干步被释放，而不改变其峰值占用。换言之，策略优化的是解码侧的能量项，显存容量项由上下文长度与并发数决定，两者不可互相替代。若把能效收益直接换算成“可以多开并发”，就会在容量规划上失准。</p>\n<p>可复算的峰值账本如下：设层数 $L$、KV 头数 $H_{kv}$、头维 $d$、每元素字节 $b$（FP8 为 1，NVFP4 为 0.5）、上下文长度 $S$、并发请求数 $B$，则单请求 KV 字节数为</p>\n<div class=\"formula\">$$M_{kv}=2\\cdot L\\cdot H_{kv}\\cdot d\\cdot S\\cdot b,\\qquad M_{peak}=B\\cdot M_{kv}+M_{w}+M_{act}$$</div>\n<p>其中因子 2 对应 K 与 V 两份，$M_w$ 为权重常驻，$M_{act}$ 为分块激活与 TMEM 工作区。以 $L=80$、$H_{kv}=8$、$d=128$、$S=32768$、FP8 为例，单请求 KV 约 0.5 GB 量级；当 $B$ 提升到数十路时，KV 迅速成为 HBM3e 的主要占用项，权重反而退居次要。此时若策略把平均生成长度压短，释放的是解码带宽与功耗，账本上的 $M_{kv}$ 峰值不变——除非配合分页与跨请求前缀复用，把相同仓库前缀的 KV 块共享，才能把容量项真正压下来。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制后果</th><th>系统代价</th></tr></thead><tbody><tr><td>无测试用例可校验</td><td>通过率约束失去反馈信号，提前终止无法判定是否安全</td><td>策略退化为固定长度，能效收益消失</td></tr><tr><td>上下文远长于生成长度</td><td>预填 KV 主导峰值占用，解码缩短不改变容量</td><td>并发上限由 $M_{kv}$ 卡死，吞吐不升</td></tr><tr><td>置信度校准偏差</td><td>过早终止导致通过率跌破阈值 $\\tau$</td><td>重试与重新预填，能耗反超基线</td></tr></tbody></table>\n<p>因此该方案的能效边界应表述为：它优化的是解码阶段的 token 级计算开销，对预填主导的长上下文场景收益有限；在缺少测试用例的补全场景中，约束项不可观测，策略不可直接套用。工程判断上，应把 GREEN-CODE 的长度策略与分页 KV、前缀复用、FP8/NVFP4 量化并列配置——前者压解码能耗，后者压容量与带宽，二者叠加才构成完整的显存与能效预算，任何单侧外推都会在容量规划上产生偏差。</p>\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-26\">二十六 · 连续批处理：把“提前终止”变成调度信号</h3>\n<p>GREEN-CODE 的策略变量落在解码阶段的生成长度上：置信度高时提前终止，不确定时继续生成。放到服务端，这个变量不能只由模型自己决定，必须被调度器看见。连续批处理（continuous batching）的迭代级调度恰好提供了这个接口——每个 decode step 结束后，调度器重新审视 batch 内每个序列的状态，完成者立即退出、等待者立即补位。对 GREEN-CODE 而言，关键是把“策略建议终止”与“序列真实结束”区分开：前者是策略层给出的软信号，后者是 EOS 或长度上限触发的硬事件。工程上应让策略输出一个终止倾向分数，调度器据此决定是否在本 step 后释放该序列的 KV 页，而不是等模型吐出 EOS 才回收。</p>\n<p>伪代码思路如下：每个 step 收集活跃序列的策略分数 $s_i$，若 $s_i &lt; \\theta$ 且该序列已生成不少于最小长度，则标记为可抢占候选；调度器按优先级排序后决定本轮 batch 组成。这里 $\\theta$ 是策略学习得到的阈值，与通过率约束 $\\tau$ 耦合——阈值越激进，能耗越低，但通过率约束越紧。</p>\n<div class=\"formula\">$$B_{t+1}=\\underset{B\\subseteq \\mathcal{Q}_t,\\ |B|\\le B_{\\max}}{\\arg\\max}\\ \\sum_{i\\in B} u_i,\\quad u_i=\\frac{\\hat{p}_i}{\\hat{c}_i}$$</div>\n<p>其中 $\\hat p_i$ 是该请求的预期通过概率，$\\hat c_i$ 是预期剩余解码能耗。代价方面：连续批处理把 batch 填充率从静态批的“最慢序列决定一切”改为按 step 动态填充，直接抬高吞吐；但每个 step 的调度开销随队列长度增长，在 NVL72 这种 72 卡域内需要把调度决策放在单卡或单节点本地完成，避免跨节点同步拖慢 step 节奏。具体例子：一个仓库级补全请求在预填后置信度迅速升高，策略在第 40 个 token 处给出终止倾向，调度器立即回收其 KV 页并把排队中的另一个短请求填入，原本空转的 decode 槽位被复用——这正是 GREEN-CODE 的“提前终止”从算法变成吞吐收益的路径。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-27\">二十七 · Chunked prefill：预填与解码的能耗结构差异</h3>\n<p>论文明确指出能耗度量覆盖预填与解码两阶段，且两者能耗结构不同。预填是计算密集型：长上下文一次性过完所有层，矩阵乘规模大、算术强度高；解码是访存密集型：每 step 只处理一个 token，却要读完整份 KV 缓存。Chunked prefill 把长预填切成固定大小的块，与解码请求混在同一 step 中执行，目的是抹平这种结构性差异带来的 GPU 利用率波动。</p>\n<p>对 GREEN-CODE 的直接含义是：预填能耗与上下文长度近似线性，而解码能耗与生成长度线性。若把预填切块，单块的计算密度下降，但换来的是 decode 请求不被长预填阻塞——尾延迟显著改善。代价是 KV 缓存写入被分散到多个 step，页表管理更频繁；在 SM100 上，tcgen05 的 TMEM 分配与 2-SM MMA 的配对需要按块粒度重新规划，块太小会浪费 MMA 的配对机会，块太大则失去混批的灵活性。</p>\n<div class=\"formula\">$$E_{\\text{total}}\\approx \\alpha\\cdot L_{\\text{ctx}}+\\beta\\cdot L_{\\text{gen}},\\quad \\frac{\\partial E}{\\partial L_{\\text{ctx}}}\\gg\\frac{\\partial E}{\\partial L_{\\text{gen}}}\\ \\text{(单位 token 计算量)}$$</div>\n<p>工程判断：chunk 大小应取使单块预填的算术强度仍能喂满 tensor core 的下限，同时保证一个 decode step 的时延预算内能塞进至少一个 chunk。具体例子：一个带 32K token 仓库上下文的补全请求，若整块预填会独占 GPU 数百毫秒，期间所有 decode 请求排队；切成若干块后，每块与在线 decode 混批，decode 的 step 间隔不再被预填尖峰拉长，尾延迟的 P99 由预填尖峰主导转为由调度队列深度主导。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-28\">二十八 · 优先级与抢占：尾延迟的源头在队列而非算力</h3>\n<p>代码生成请求的时延敏感度并不齐平：IDE 内联补全要求极低首 token 延迟，而仓库级重构、工具调用循环可以容忍更长时延。若不分优先级，一个长上下文预填就能把交互式补全的尾延迟推高一个数量级。优先级调度要解决的是“谁先占 SM”和“谁先占 KV 页”两个资源维度。</p>\n<p>抢占的实现依赖 KV 页的可换出性：被抢占序列的 KV 页写回主机内存或降级到更低带宽的存储层，释放 device 显存给高优先级请求。代价是换出/换入的带宽开销——在 NVLink 5 域内，节点间换出比 PCIe 快，但仍是数量级低于 HBM 的带宽；频繁抢占会把尾延迟从“排队等待”转成“换页等待”，未必更优。因此抢占策略应设一个最小驻留时间，避免短序列被反复换出。</p>\n<div class=\"formula\">$$\\text{P99}=\\max_{\\text{path}}\\left(\\sum_{\\text{queue}} w_q+\\sum_{\\text{preempt}} \\frac{S_{\\text{kv}}}{BW_{\\text{swap}}}\\right)$$</div>\n<p>具体例子：NVL72 内一个 72 卡域同时服务多个租户，交互式补全请求被标记为高优先级，仓库级请求为低优先级。当高优先级请求到达而 device 显存不足时，调度器选择换出低优先级序列中驻留时间最长、剩余生成长度最大的那个——因为它的换出收益最高（释放页多）而损失最小（本来就要生成很久）。这把尾延迟的方差压下来，代价是低优先级请求的完成时间被拉长，需要在 SLO 上分别设定两类请求的时延目标。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-29\">二十九 · 分离式预填/解码：把两种能耗结构放到不同硬件档位</h3>\n<p>预填计算密集、解码访存密集，二者对 GPU 的资源偏好相反。分离式（disaggregated）预填/解码把两个阶段放到不同的 worker 池：预填池追求高算力密度，解码池追求大显存与高带宽，KV 缓存通过 NIXL 在池间传输。对 GREEN-CODE 而言，这正好对应其能耗度量的两阶段拆分——预填能耗在预填池计量，解码能耗在解码池计量，策略学习可以分别对两段施加不同的长度控制。</p>\n<p>代价核心在 KV 传输：一个长上下文请求的 KV 体量与其层数、头数、上下文长度成正比，跨池传输占用 NVLink 带宽，且传输时延直接进入首 token 延迟。若预填池与解码池在同一 NVL72 域内，传输走 NVLink 5；跨域则退化到网络层，时延与带宽都变差。工程上应让预填池按请求的上下文长度做亲和性路由，尽量把同一请求的预填与后续解码放在同一域内。</p>\n<div class=\"formula\">$$T_{\\text{ttft}}=T_{\\text{prefill}}+\\frac{S_{\\text{kv}}}{BW_{\\text{nixl}}}+T_{\\text{queue}},\\quad S_{\\text{kv}}\\propto n_{\\text{layer}}\\cdot n_{\\text{head}}\\cdot d_{\\text{head}}\\cdot L_{\\text{ctx}}$$</div>\n<p>具体例子：工具调用循环中，每轮都要把工具返回结果拼进上下文重新预填。分离式架构下，预填池可以批量处理这些增量预填，解码池保持常驻的会话 KV；但每轮的 KV 增量都要跨池同步，若同步走 NIXL 且增量较小，传输开销占比会上升。判断点在于：当增量预填的 KV 体量相对于已有缓存很小时，合并回同池执行反而更省——分离式的收益只在预填与解码的负载比例严重失衡时才成立。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-30\">三十 · 时延与吞吐的取舍：把策略阈值当作调度旋钮</h3>\n<p>GREEN-CODE 的优化目标是质量约束下的能耗最小化，没有显式的时延项。但部署时能耗与吞吐、时延是同一枚硬币：提前终止减少 token 数，既降能耗也降单请求时延，却可能降低通过率；加大 batch 提高吞吐，却拉长单请求排队时延。策略阈值 $\\theta$ 因此不只是算法参数，而是调度旋钮——调高 $\\theta$ 使更多序列提前终止，吞吐上升、能耗下降、通过率承压；调低则相反。</p>\n<p>把 $\\theta$ 暴露为服务级配置，按请求类别分别设定：交互式补全用低 $\\theta$ 保通过率，批量重构用高 $\\theta$ 换吞吐。这与论文的质量约束 $\\tau$ 形成对应——$\\tau$ 是全局约束，$\\theta$ 是局部执行手段。代价是监控复杂度上升：需要按类别分别统计通过率与能耗，否则全局通过率会被高 $\\theta$ 类别拉低而掩盖问题。</p>\n<div class=\"formula\">$$\\max_{\\theta}\\ \\text{Throughput}(\\theta)\\quad \\text{s.t.}\\ \\text{PassRate}(\\theta)\\ge\\tau,\\ \\text{P99}(\\theta)\\le \\text{SLO}$$</div>\n<p>具体例子：一个 CI 场景批量生成单元测试，通过率要求宽松、吞吐优先，$\\theta$ 调高后大量序列在置信度尚可时提前终止，decode 槽位快速轮转；同一集群的 IDE 补全通道用独立队列与低 $\\theta$，两条通道共享 GPU 但按优先级隔离。这种“同硬件、双策略”的部署形态，正是 GREEN-CODE 的可学习策略在 Blackwell 上落地的现实形态——策略不是全局一个数，而是按 SLO 分档的一组阈值。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-31\">三十一 · 尾延迟怎么压：从测量缺口到工程闭环</h3>\n<p>论文的局限之一是没有给出批大小、并发与上下文长度分布，因此无法评估批调度对能耗的实际影响；能耗测量也未给出硬件档位与精度细节。这意味着 GREEN-CODE 的能耗结论在跨平台复现时不可比。对部署者的直接后果是：不能直接拿论文的能耗比例做容量规划，必须在本地的 B200/B300 档位上重建测量闭环。</p>\n<p>闭环的最小构成是：按请求类别打标（交互/批量/工具循环），分别记录预填 token 数、解码 token 数、策略终止位置、KV 页驻留时长与换出次数；用这些量对齐 GREEN-CODE 的两阶段能耗模型，得到本地化的 $\\alpha,\\beta$ 系数。尾延迟的压缩则落在三个具体机制上：chunked prefill 削平预填尖峰、优先级抢占限制长请求对短请求的阻塞、分离式部署把预填与解码的负载波动解耦。三者不是叠加越多越好——每增加一层，KV 传输与页管理的开销就多一分，判断依据是 P99 的主导项落在哪：若主导项是排队，优先做优先级；若主导项是预填阻塞，优先做 chunked prefill；若主导项是显存不足导致的换出，优先做分离式扩容解码池。</p>\n<p>具体机制上，建议把策略终止位置作为一等监控指标与调度输入：当某类请求的平均终止位置持续前移而通过率未降，说明 $\\theta$ 偏保守，可上调换吞吐；当通过率逼近 $\\tau$ 而下尾延迟仍高，说明瓶颈不在生成长度而在预填或队列，应转向 chunk 与优先级调整。这把 GREEN-CODE 的“生成长度控制”从一个离线学习到的策略，变成在线可观测、可调节的调度反馈环——能耗目标由此落到具体机制上，而不是停留在论文的期望能耗公式里。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-32\">三十二 · 能效策略撞上批调度：边界、失效条件与系统代价</h3>\n<p>GREEN-CODE 的策略作用点是解码阶段的生成长度，它本身不感知批。一旦放进连续批处理与 chunked prefill 的调度器里，提前终止就不再是单请求的私事：某个请求被策略判定“置信度足够”而截断，它释放的 KV 缓存块会立刻被调度器分配给新请求，批的组成随之改变，后续 step 的 token 预算与显存占用全部重排。于是能耗度量必须从“单条轨迹的预填+解码能耗”上升到“批级每 step 能耗除以有效 token 数”，否则策略学到的节能量在并发下会被批内其他请求的填充与重算稀释。更硬的约束是 chunked prefill：长上下文仓库级补全的预填被切成多个 chunk 与解码请求混跑，预填能耗被摊薄但尾延迟被拉长，策略若只按总能耗最小化，会倾向把不确定的请求拖到更晚的 chunk，牺牲的是 p99 而非均值。</p>\n<p>把质量约束写成批级形式，失效条件就显式了。设批内请求集合为 \\(B\\)，策略 \\(\\pi\\) 对请求 \\(i\\) 的生成长度决策为 \\(l_i\\)，则调度器实际承受的代价近似为</p>\n<div class=\"formula\">$$\\mathcal{E}_{B}(\\pi)=\\sum_{i\\in B}\\big[E_{\\text{prefill}}(c_i)+l_i\\cdot E_{\\text{decode}}\\big],\\qquad \\text{s.t.}\\ \\frac{1}{|B|}\\sum_{i\\in B}\\mathbb{1}\\{\\text{pass}(\\pi,x_i)\\}\\ge\\tau$$</div>\n<p>问题在于约束是批平均通过率，而抢占与优先级会打破这个平均：高优先级请求抢占低优先级请求的 KV 块时，被抢占者需要重算预填或从 CPU 侧换回，这部分能耗不计入任何单条轨迹，却真实发生在 SM 与 HBM 上。策略在训练时看到的通过率来自独立采样轨迹，部署时却面对被抢占后上下文不完整的请求，通过率约束的统计基础被削弱，这是该方法在分离式预填/解码架构下最典型的失效条件——预填节点与解码节点分处不同 GPU 池，策略的终止信号要跨节点回传，回传延迟本身构成能耗与尾延迟的额外项。</p>\n<p>工程判断落在取舍上：若把策略的提前终止阈值调紧，解码 token 数下降、批吞吐上升，但通过率约束在长尾请求上更容易被击穿，且尾延迟的改善有限，因为尾延迟主要由预填 chunk 的排队与 KV 换入换出决定，而非解码长度；若调松，能耗收益被批内填充与重算吃掉。可行的做法是把策略输出当作调度器的提示而非硬决策：终止请求进入低优先级队列等待校验，校验通过的释放 KV 块，未通过的按剩余预算续解，同时把抢占重算能耗计入批级度量，使 \\(\\mathcal{E}_B\\) 包含换入换出项。这样能耗目标与 SLO 才在同一坐标系里，容量规划也才有可测的输入。</p>\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-33\">三十三 · 并行切分的四轴与代码生成负载的匹配</h3>\n<p>在 Blackwell 上把 GREEN-CODE 这类“预填重、解码长、请求异构”的代码生成负载跑快，第一步不是选框架，而是决定把模型和请求切到哪几个轴上。TP（张量并行）切的是单层内的权重矩阵，每层后必须做一次 All-Reduce 或 Reduce-Scatter，通信量与隐层宽度和 batch 成正比；EP（专家并行）切 MoE 的专家，token 被路由到不同 rank，通信形态是 All-to-All，且是“稀疏、不规则、随 batch 组成抖动”的；PP（流水并行）切层，通信只在 stage 边界传激活，量小但要求微批填满流水线，否则气泡吃掉吞吐；DP（数据并行）切请求，只在权重梯度场景需要通信，推理时几乎零通信，但要求每张卡都有完整权重副本，直接吃掉显存预算。对代码生成而言，请求长度分布极不均匀——短补全几十 token，仓库级补全带长上下文预填——这决定了 DP 在解码阶段最划算，而长上下文预填阶段 TP 更必要，因为单卡放不下激活与 KV。</p>\n<p>切分选择的代价可以直接写成通信占比：设单层计算时间为 <span class=\"inline-math\">T_comp</span>，集合通信时间为 <span class=\"inline-math\">T_comm</span>，则该层有效利用率为 <span class=\"inline-math\">T_comp/(T_comp+T_comm)</span>。TP 度数为 <span class=\"inline-math\">N</span> 时，All-Reduce 的数据量为 <span class=\"inline-math\">2(N-1)/N · B·S·H·bytes</span>（B 为微批、S 为序列长、H 为隐层），而计算量随 N 近似线性下降，于是存在一个临界 N，超过它通信开始主导。Blackwell 的 NVLink 5 把单链路带宽抬到每 GPU 双向 1.8 TB/s 量级、NVL72 机柜内通过 NVSwitch 做全互联，正是把这个临界点往大 N 推；但一旦跨出机柜走 InfiniBand，带宽掉一个数量级，TP 就必须收缩到机柜内。工程判断很直接：TP 与 EP 的并行度上限由“是否还在 NVLink 域内”决定，而不是由显存缺口决定。</p>\n<p>具体例子：一个仓库级补全请求预填 32K token 上下文，若 TP=8 在机柜内，每层 All-Reduce 传的是 8 卡分摊后的激活，NVSwitch 全互联下延迟被压到微秒级，预填的算力密度得以维持；若把同一模型拆到两个机柜做 TP=16，跨域那段 All-Reduce 立刻成为预填阶段的主项，预填延迟抬升而 GPU 空转，能耗随之上升——这与 GREEN-CODE 关心的“预填与解码能耗结构差异”直接相关，因为预填是算力密集、通信敏感，解码是带宽与显存密集、通信相对不敏感。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-34\">三十四 · All-Reduce 与 All-to-All 的代价结构差异</h3>\n<p>All-Reduce 是结构化、可预测的：Ring 或 Tree 算法下，通信时间近似 <span class=\"inline-math\">2(N-1)/N · M/BW + α·log N</span>，M 是消息大小，α 是单跳延迟。它的关键性质是“每个 rank 的发送量固定、与路由无关”，因此可以靠把多个小消息聚合（bucket fusion）来摊薄 α。TP 的每层 All-Reduce 天然适合融合：把相邻层的梯度式通信合并成大 bucket，让 α 占比下降。代价是显存——bucket 要暂存，长上下文预填时激活本就吃紧，bucket 太大会挤占 KV 空间。</p>\n<p>All-to-All 是另一回事。EP 下每个 token 被 top-k 路由到若干专家，发送量取决于路由分布：热门专家所在 rank 收到大量 token，冷门 rank 几乎空闲，形成“通信长尾”。其代价不能只用平均带宽描述，必须看最大 rank 的负载：<span class=\"inline-math\">T_all2all ≈ max_i (M_i)/BW + α·N</span>，其中 <span class=\"inline-math\">M_i</span> 是 rank i 的收发量。代码生成负载里，token 语义高度集中（关键字、常见 API 名、缩进结构），路由分布比自然语言更偏斜，长尾更明显。这意味着 EP 在代码场景下要么配 capacity factor 做 token 丢弃/重排，要么用冗余专家（redundant experts）把热点摊开，两者都以质量为代价或显存为代价。</p>\n<p>表格对比两种通信在代码生成两阶段的表现：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>All-Reduce（TP）</th><th>All-to-All（EP）</th></tr></thead><tbody>\n<tr><td>消息规律性</td><td>固定大小、每层一次</td><td>随路由抖动、每 MoE 层一次</td></tr>\n<tr><td>瓶颈判据</td><td>总带宽 × 层数</td><td>最大 rank 负载（长尾）</td></tr>\n<tr><td>预填阶段影响</td><td>高（算力密集，通信占比抬升）</td><td>中（token 多但可批处理摊薄）</td></tr>\n<tr><td>解码阶段影响</td><td>低（每步消息小，α 主导）</td><td>高（每步都 All-to-All，α 无法摊薄）</td></tr>\n<tr><td>优化手段</td><td>bucket 融合、NVLS 多播</td><td>capacity factor、冗余专家、分层 All-to-All</td></tr>\n</tbody></table>\n<p>解码阶段每生成一个 token 就要过一次 All-to-All，消息小到 α 主导，这是 EP 在低 batch 解码时最痛的地方。GREEN-CODE 的策略在置信度高时提前终止生成，恰好减少了“每步都付一次 All-to-All α”的次数——这是一个被论文未明说、但在 Blackwell EP 部署下真实存在的能效耦合：少生成 token 不仅省算力，还省掉固定延迟的集合通信开销。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-35\">三十五 · NIXL 传输与分离式预填/解码的通信面</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）把预填与解码放到不同 GPU 池，KV 缓存必须从预填节点搬到解码节点。这一步的传输层在 Blackwell 部署里通常由 NIXL 承担：它把 KV 块描述为可点对点拉取的内存区域，绕过主机内拷贝，直接在 GPU 显存之间做 RDMA 或 NVLink 传输，并按块粒度流水。传输代价是 <span class=\"inline-math\">T_kv = KV_bytes/BW_link + 固定握手</span>，KV_bytes 随层数、头数、序列长线性增长，长上下文仓库级补全的 KV 块可达数百 MB 量级，此时链路带宽直接决定首 token 延迟。</p>\n<p>关键机制是“块级流水 + 与解码计算重叠”：解码节点不必等整个 KV 到齐才开始，可以按层或按块边收边算，把传输时间藏在第一层计算之后。这要求预填端按解码端的消费顺序发送，而不是按自己的写出顺序。代价是调度复杂度：如果预填池与解码池的请求配比失衡，KV 传输会在某一侧堆积，形成显存峰值——预填端要暂存待发 KV，解码端要预留接收缓冲，两边都吃掉本可用于 batch 的显存。</p>\n<p>具体例子：一个工具调用循环里，模型先生成调用参数、等工具返回、再续写代码。若用分离式部署，每次循环都要把增长的 KV 从预填池同步到解码池；若 NIXL 传输没有和下一轮预填重叠，循环的每轮首 token 延迟就被传输主导，GPU 在等数据时闲置，能耗白白消耗在待机上。工程判断是：分离式只在“预填与解码的算力特征差异足够大、且 KV 传输能被重叠隐藏”时才划算，否则合并部署反而省掉整条传输链路。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-36\">三十六 · 通信何时成为瓶颈的判据</h3>\n<p>不要凭感觉判断“通信是不是瓶颈”，用可测量的比值。定义单步解码的通信-计算比 <span class=\"inline-math\">R = T_comm/T_comp</span>，在 TP 下 <span class=\"inline-math\">T_comp ∝ B·H²·L</span>（L 为层数），<span class=\"inline-math\">T_comm ∝ L·B·H·bytes/BW</span>，于是 <span class=\"inline-math\">R ∝ H·bytes/(BW)</span>，与 batch 无关——这说明 TP 的通信占比在解码阶段由模型宽度和链路带宽决定，加 batch 救不了它，只有加带宽或减宽度才行。这解释了为什么 NVL72 机柜内的 TP 能撑住大模型解码，而跨机柜 TP 在解码阶段几乎必然被通信压死。</p>\n<p>第二个判据是“通信是否在关键路径上”。All-Reduce 在 TP 里是每层必经，天然在关键路径；All-to-All 在 EP 里也是每 MoE 层必经。真正可优化的是“能否重叠”：把通信与下一层的非依赖计算交错，或用 NVLS 的多播/归约在交换机内完成，减少端点拷贝。Blackwell 的 NVSwitch 支持在交换机内做归约，把 All-Reduce 的一部分工作从 GPU 端点挪到交换平面，端点只发一次收一次，α 被摊薄。代价是交换机资源成为共享瓶颈，多租户下会互相干扰。</p>\n<p>第三个判据落在能耗上：通信本身功耗不高，但通信造成的 GPU 空转功耗很高。设空转占比 <span class=\"inline-math\">u = T_comm/(T_comm+T_comp)</span>，则有效能耗近似为 <span class=\"inline-math\">E_eff = E_total/(1-u)</span>。GREEN-CODE 的能耗度量若只统计计算，会低估通信造成的浪费；把 u 纳入度量，才能解释为什么同样的通过率下，切分方案不同能耗差出一截。论文材料未给出硬件档位与测量方法，这正是其能耗结论跨平台不可比的根源之一。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-37\">三十七 · 代码生成负载下的切分决策</h3>\n<p>把上面几条合成一个可执行的决策顺序。第一，看请求形态：短补全为主则 DP 优先、TP 最小化，因为解码阶段通信占比高而单请求算力需求低；仓库级长上下文为主则预填阶段必须 TP，且 TP 度数卡在 NVLink 域内。第二，看模型是否 MoE：若是，EP 的 All-to-All 在解码阶段是固定税，必须用冗余专家或分层 All-to-All 压长尾，且 EP 度数要与 TP 度数联合优化——常见做法是“机柜内 TP+EP、机柜间 DP”，让所有集合通信留在 NVSwitch 域。第三，看是否分离式：只有当 KV 传输能被 NIXL 流水重叠、且预填/解码配比稳定时才启用，否则合并部署省掉整条链路。</p>\n<p>伪代码思路（调度器侧的切分选择）：</p>\n<div class=\"formula\">$$\\text{choose } (N_{tp},N_{ep},N_{pp},N_{dp}) \\ \\text{s.t.}\\ N_{tp}\\cdot N_{ep}\\cdot N_{pp}\\cdot N_{dp}\\le N_{gpu},\\ \\ N_{tp}\\cdot N_{ep}\\le N_{nvlink},\\ \\ \\max R_{stage}\\le R_{budget}$$</div>\n<p>其中 <span class=\"inline-math\">N_nvlink</span> 是单个 NVLink 域内的 GPU 数，<span class=\"inline-math\">R_budget</span> 是允许的通信-计算比上限（由 SLO 反推）。这个约束把“通信何时成为瓶颈”变成了容量规划里的硬边界：一旦某阶段的 R 超过预算，就要么缩并行度、要么换更宽的链路、要么把该阶段拆到独立池。</p>\n<p>具体例子：NVL72 机柜里跑一个 MoE 代码模型，TP=8 放在机柜内、EP=8 也在机柜内、跨机柜用 DP=9 铺满 72 卡。预填阶段 TP 的 All-Reduce 走 NVSwitch，解码阶段 EP 的 All-to-All 也在域内，跨机柜只有请求级分发，几乎零通信。若把 EP 拆到两个机柜，解码每步的 All-to-All 跨域，α 与带宽双重恶化，GREEN-CODE 那种“提前终止省 token”的收益会被通信固定开销吃掉大半——省下的计算被等通信的时间抵消，能耗不降反升。这就是切分决策必须先于解码策略优化的原因：策略调的是 token 数，切分调的是每个 token 的固定成本。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-38\">三十八 · 并行拓扑的能耗边界：通信何时吃掉 GREEN-CODE 的收益</h3>\n<p>GREEN-CODE 把优化变量压在解码阶段的生成长度与提前终止上，这个变量与并行切分之间存在直接耦合：策略越激进地缩短解码步数，单步内可摊销的通信量就越少，通信开销在总能耗中的占比反而上升。以张量并行（TP）为例，每层前向含两次 All-Reduce，单次解码步的通信量约为 <span class=\"formula\">$$V_{\\text{comm}} \\approx 2 \\cdot L \\cdot b \\cdot s \\cdot h \\cdot d \\cdot \\frac{N-1}{N}$$</span>（L 为层数、b 为批、s 为序列长度、h 为隐维、d 为字节宽度、N 为 TP 度），而计算量随 s 线性增长、通信量同样随 s 线性增长——预填阶段通信/计算比稳定，解码阶段 s=1 时通信占比被放大到极致。在 NVLink 5 与 NVSwitch 全互联的 GB200 NVL72 机柜内，All-Reduce 带宽足够高，TP 度 8 以内通常不构成瓶颈；一旦跨机柜走 InfiniBand，同样的 All-Reduce 延迟抬升一个量级，GREEN-CODE 省下的那部分解码能耗会被通信功耗抵消。工程判断是：把 TP 度锁在单 NVLink 域内，跨域只做 DP 或 PP。</p>\n<p>专家并行（EP）的代价结构不同：MoE 每层需两次 All-to-All，通信量与激活的 token 数乘以被路由的专家数成正比，且对负载均衡极度敏感。GREEN-CODE 的提前终止会让不同请求的解码长度差异变大，批内 token 数在时间上不再均匀，All-to-All 的尾延迟由最长请求决定，短请求省下的能耗被长请求的等待抵消。NIXL 在此处的价值是把 KV 缓存与激活的传输从集合通信中拆出来，做成点对点、可异步的搬运，使分离式预填/解码的 P 节点与 D 节点之间不必维持同步的集合语义；但 NIXL 只降低传输开销，不改变 EP 路由不均衡本身。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>主要通信原语</th><th>GREEN-CODE 下的失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>TP</td><td>每层 All-Reduce</td><td>解码步被提前终止压缩，通信占比升高</td><td>跨域时延迟主导，能耗收益被抵消</td></tr><tr><td>EP</td><td>每层 All-to-All</td><td>批内解码长度离散，路由不均衡</td><td>尾延迟由最长请求决定</td></tr><tr><td>PP</td><td>激活点对点</td><td>流水气泡随解码步变短而变大</td><td>stage 间空转功耗</td></tr><tr><td>DP</td><td>梯度/参数广播（推理仅权重加载）</td><td>无</td><td>权重副本占显存</td></tr></tbody></table>\n<p>流水并行（PP）在 GREEN-CODE 场景下最脆弱：气泡比例近似 <span class=\"formula\">$$\\text{bubble} \\approx \\frac{P-1}{m+P-1}$$</span>（P 为 stage 数、m 为微批数），解码阶段微批本就少，提前终止进一步减少有效步数，stage 间空转的静态功耗摊不薄。因此该方案在 PP 度大于 2 的部署上收益最不确定。真正决定通信是否成为瓶颈的判据是单步通信时间与单步计算时间之比：当该比值超过约一成，GREEN-CODE 在解码侧省下的能耗已不足以覆盖通信侧的增量，此时应优先降低并行度、改用更大的单卡显存承载 KV 缓存，而不是继续堆切分。</p>\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-39\">三十九 · 精度塌陷：从“通过率掉点”到可归因的数值链路</h3>\n<p>GREEN-CODE 的优化变量落在解码阶段的生成长度与策略选择上，它本身不改变权重精度；但在 Blackwell 上落地时，策略层与数值层会耦合出新的失败面。典型表现是：策略在置信度较高时提前终止生成，代码语法完整、能编译，但边界条件缺失，测试用例通过率相对基线出现系统性下滑。这类塌陷不是模型“变笨”，而是终止判据与数值置信度之间的错配——NVFP4/FP8 下 logits 分布的尾部被压缩，softmax 置信度被高估，策略误判“已足够确定”。诊断的关键是把通过率下降拆成两段：预填阶段的上下文编码是否失真（KV 缓存中的键值在低精度下累积误差），解码阶段的终止点是否提前。工程上可做一次“精度回切”对照：同一批请求分别跑 FP8 与 BF16 解码，只比较策略终止位置的分布偏移；若终止点前移集中在长上下文请求上，则问题在预填侧 KV 精度，而非策略本身。</p>\n<div class=\"formula\">$$\\Delta_{\\text{pass}}=\\underbrace{\\left(\\mathbb{E}[\\mathbb{1}\\{\\text{pass}\\}]_{\\text{FP8}}-\\mathbb{E}[\\mathbb{1}\\{\\text{pass}\\}]_{\\text{BF16}}\\right)}_{\\text{数值塌陷}}+\\underbrace{\\left(\\mathbb{E}[\\mathbb{1}\\{\\text{pass}\\}]_{\\text{BF16}}-\\mathbb{E}[\\mathbb{1}\\{\\text{pass}\\}]_{\\pi}\\right)}_{\\text{策略塌陷}}$$</div>\n<p>代价上，精度回切对照会让单卡吞吐下降，因为 BF16 解码的显存带宽占用约为 FP8 的两倍，KV 缓存容量减半，连续批处理的有效批大小随之收缩；这正是诊断窗口必须短、采样必须分层的原因。具体例子：仓库级补全请求上下文长、生成短，若在 FP8 下把终止阈值调紧，通过率掉点会集中在“需要跨文件符号解析”的样本上，而单文件函数题几乎不受影响——这个分布差异本身就是定位信号。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-40\">四十 · OOM 与批抖动：容量边界上的连锁反应</h3>\n<p>OOM 在 Blackwell 推理栈里很少是单一原因，更多是“批大小 × 上下文长度 × KV 缓存精度”三者乘积越界。GREEN-CODE 的策略会动态改变生成长度，意味着同一批内各请求的解码步数方差变大；连续批处理在某个 decode step 后集中回收已完成序列、又集中接纳新请求，瞬时 KV 分配出现尖峰。若调度器按平均长度预留显存，尖峰就会触发 OOM 或强制驱逐，驱逐又造成重算预填，预填能耗被重复计入——这与论文“能耗度量覆盖预填与解码两阶段”的口径直接冲突，监控上表现为能耗指标虚高而通过率不变。批抖动的量化可以用批内解码步数的变异系数刻画：</p>\n<div class=\"formula\">$$\\mathrm{CV}_{\\text{steps}}=\\frac{\\sigma(\\text{len}_{\\text{decode}})}{\\mu(\\text{len}_{\\text{decode}})},\\qquad \\text{峰值 KV}\\approx B\\cdot \\bar{L}_{\\text{ctx}}\\cdot d\\cdot s\\cdot b_{\\text{kv}}$$</div>\n<p>其中 B 为并发批、L̄ 为平均上下文、d 为层数、s 为序列槽位、b 为每元素字节数。CV 越大，按均值预留越危险。工程判断是：把策略的终止分布纳入容量规划，按 P95 而非均值预留 KV，并对长上下文请求单独设池。代价是显存利用率下降、单位 token 成本上升，但换来的是 OOM 归零与预填重算消除。具体例子：NVL72 机架内多副本共享 NVLink 5 域，一个副本因 OOM 驱逐引发的重算会通过集合通信拖慢同域其他副本的 all-reduce 节奏，尾延迟在整机架层面被放大。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-41\">四十一 · 尾延迟：策略不确定性与解码长尾的叠加</h3>\n<p>GREEN-CODE 的策略在“不确定时继续生成”，这直接把不确定性转译成解码步数的长尾。尾延迟的根因有两层：一是策略自身的置信度判据在分布外请求上失效，反复试探；二是 Blackwell 上 2-SM MMA 与 TMEM 的占用使单个长序列解码与同批短序列争用同一组 tensor core 周期，长尾请求拉长整个批的完成时间。诊断应看 P99 与 P50 的比值而非均值，并把长尾请求按“策略终止置信度分桶”统计：若 P99 集中在低置信度桶，说明是策略保守而非硬件瓶颈。可用的伪代码思路是给每个请求记录解码步数与终止置信度，离线聚合出分桶尾延迟：</p>\n<ul>\n<li>记录 (request_id, decode_steps, terminal_confidence, prefill_len)；</li>\n<li>按 terminal_confidence 分位分桶，计算各桶 P99 解码步数；</li>\n<li>若低置信度桶 P99 显著高于高置信度桶，则尾延迟由策略驱动，应调终止判据而非加卡；</li>\n<li>若各桶 P99 接近而 P50 差异大，则瓶颈在批调度与抢占，应查连续批处理的准入策略。</li>\n</ul>\n<p>代价上，压低尾延迟的常见手段是给长尾请求单独的小批通道，牺牲吞吐换 SLO；在分离式预填/解码部署中，这意味着解码池要预留一部分低利用率槽位。具体例子：工具调用循环里模型反复生成短片段并等待外部返回，策略在每轮都重新判断置信度，轮次间的尾延迟被累乘，单请求 P99 可远超单轮 P99——监控必须按会话而非按单次生成聚合。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-42\">四十二 · 静默降级：没有报错的能效回退</h3>\n<p>最危险的失败模式是不报错。GREEN-CODE 的能耗度量依赖对预填与解码两阶段的统计，若采集点缺失（例如策略提前终止后跳过了能耗记账、或 KV 缓存命中被误计为预填），系统会“看起来更省”而实际通过率未变甚至下降。静默降级的另一来源是量化档位漂移：运维为压显存把某些层切到更低精度，通过率在测试集上无感，但在长上下文仓库级请求上缓慢劣化。监控必须建立“能效-质量”双轴基线：单位通过样本的能耗（焦耳/通过用例）作为主指标，任何能耗下降若伴随该比值不变而通过率分子缩小，即为静默降级信号。工程上应把能耗采集做成与生成路径解耦的旁路，避免策略终止逻辑影响记账完整性；回滚则以“精度档位 + 策略阈值”作为一个原子配置版本管理，任一指标越界即整版回退，而非逐参数调。</p>\n<p>代价是旁路采集带来额外的主机侧开销与同步点，在高并发下可能引入微秒级抖动；但相比静默降级导致的容量规划失准（按虚低能耗扩容，实际 SLO 不达标），这个代价是必要的。具体例子：某副本在 FP8 下能耗指标改善，但焦耳/通过用例持平、通过率绝对值下降，说明省下的是“没生成完的 token”而非真实效率提升——这正是 GREEN-CODE 质量约束 τ 在监控侧应被显式校验的原因。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-43\">四十三 · 回滚与定位：把策略版本当作可回退的部署单元</h3>\n<p>定位路径应遵循“先分层、再分桶、后回切”：先判断塌陷发生在预填还是解码（对照 KV 精度与终止点分布），再按请求类型分桶（单文件、仓库级、工具调用循环），最后做精度或策略的单变量回切。回滚单元不是单个阈值，而是（量化档位、KV 缓存精度、策略终止判据、批调度准入）四元组，因为 GREEN-CODE 的能耗收益来自这四者的联合作用，单独回退一项可能把能耗打回原点却留下质量缺口。可操作的判据是：以通过率约束 τ 为硬门限，以焦耳/通过用例为软目标，硬门限越界立即回滚整版，软目标劣化超过预设带宽则进入灰度观察。代价上，四元组版本化意味着每次变更都要跑一轮分层采样验证，验证本身消耗 GPU 时；但对依赖测试用例反馈的策略学习而言，没有测试用例的补全场景本就无法闭环，回滚机制是唯一的安全网。具体例子：当策略在无测试用例的补全流量上被启用时，通过率无法在线判定，此时应以“终止步数分布偏移”作为代理指标触发回滚，而不是等待离线评测。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-44\">四十四 · 能效策略的失效边界：从“提前终止”到“静默降级”的连锁诊断</h3>\n\n<p>GREEN-CODE 的可学习策略只在解码阶段调节生成长度，这一变量维度极窄，因此它的失效模式高度集中在“终止判据被误用”上。策略在置信度较高时提前终止，本质是用模型自身的概率信号替代功能正确性信号；当代码结构要求跨行闭合（如嵌套括号、多分支异常处理）而模型对尾部 token 的置信度虚高时，提前终止会直接产出语法不完整或语义残缺的代码。这类失败不会触发任何运行时异常，属于典型的<strong>静默降级</strong>：请求成功返回、延迟下降、能耗下降，但通过率塌陷。诊断上必须把“策略终止位置”与“测试用例首次失败位置”对齐统计，若前者系统性早于后者，即判定为终止判据失准。系统代价体现在监控侧——需要在每次生成后额外跑一遍测试用例，这部分校验开销在材料中明确未计入能耗统计，实际部署中它会吃掉相当比例的能效收益，尤其在小 batch、短请求场景下，校验的固定开销可能超过解码节省的能耗。</p>\n\n<p>第二类失效是<strong>批抖动与尾延迟</strong>。策略使每个请求的生成长度动态变化，同一 batch 内各序列的终止时刻不再对齐，连续批处理调度器被迫在序列退出与补位之间频繁重排，形成吞吐的周期性抖动。设批内序列数为 $B$，第 $i$ 条序列的终止步数为 $L_i$，则批的有效占用率为 $\\rho=\\frac{\\sum_i L_i}{B\\cdot\\max_i L_i}$；策略越激进，$L_i$ 的方差越大，$\\rho$ 越低，GPU 在最长序列尾部处于低占用状态，尾延迟由 $\\max_i L_i$ 主导而非均值。这与能效目标直接冲突：能耗按时间积分，尾部空转的 SM 仍在耗电。定位手段是采集每步的活跃序列数与 SM 占用率，若两者在批末期同步下滑，即为策略引起的批抖动，而非调度器缺陷。</p>\n\n<p>第三类是<strong>精度塌陷与 OOM 的耦合</strong>。材料未给出量化方案，但若部署侧叠加 NVFP4/FP8 以放大能效收益，则需注意策略的置信度信号本身对数值精度敏感：低精度下 logits 分布的尾部被压缩，模型对“不确定”的感知变钝，提前终止的触发点前移，通过率约束 $\\mathbb{E}[\\mathbb{1}\\{\\text{pass}\\}]\\ge\\tau$ 被悄悄突破而监控指标仍显示正常。OOM 则来自另一条路径——策略在不确定时继续生成，长上下文仓库级补全的 KV 缓存随生成长度线性增长，若批内多条序列同时进入“继续生成”分支，KV 峰值显存会超出静态预留。回滚设计应把策略版本与量化档位、KV 预留上限绑定为同一配置单元，任一指标越界即整体回退到保守的固定长度解码，而非单独关闭策略——单独关闭会留下量化引起的置信度偏移，问题依旧潜伏。</p>\n\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>定位手段</th><th>回滚粒度</th></tr></thead><tbody><tr><td>静默降级</td><td>通过率降、能耗降、延迟降</td><td>终止位置 vs 首个失败位置</td><td>策略阈值上调</td></tr><tr><td>批抖动</td><td>批占用率 $\\rho$ 下滑、尾延迟抬升</td><td>每步活跃序列数</td><td>批内长度分桶</td></tr><tr><td>精度塌陷</td><td>置信度分布尾部收缩</td><td>logits 熵对比高精度基线</td><td>量化档位整体回退</td></tr><tr><td>OOM</td><td>KV 峰值越界</td><td>按序列追踪 KV 增量</td><td>KV 预留上限收紧</td></tr></tbody></table>\n\n<p>监控的最小闭环是把通过率、能耗、尾延迟三者做成同一时间窗内的联合指标，任一维度单独优化都会掩盖另外两个的退化。工程判断上，GREEN-CODE 的能效收益在有无测试用例两种场景下不可直接迁移：有测试用例时反馈信号完整，策略可收敛；无测试用例的仓库级补全场景中，策略缺少正确性锚点，此时应退化为固定长度加保守置信度阈值，把能效优化让位于正确性保障，直到引入静态分析或编译校验作为替代反馈源。</p>\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-45\">四十五 · 度量口径：预填与解码必须分开记账</h3>\n<p>GREEN-CODE 把能耗写成两段之和，这个拆分不是形式主义，而是决定了你能否在 Blackwell 上做容量规划。预填阶段是一次性大矩阵乘，算力密集、带宽压力集中在权重读取与 KV 写入；解码阶段是逐 token 的自回归循环，每步只做一次瘦 GEMM 加一次全量 KV 读取，天然带宽受限。两段的能耗曲线形状完全不同：预填的能耗近似与上下文长度线性、与批内 token 总数成正比；解码的能耗近似与生成 token 数乘以每步 KV 读取字节数成正比。论文的优化变量落在解码段的生成长度上，因此它真正压缩的是第二项。</p>\n<p>工程上要把这个口径落成可采集的量。对一次请求，记预填能耗 $E_{\\text{pre}}$ 与解码能耗 $E_{\\text{dec}}$，则</p>\n<div class=\"formula\">$$E_{\\text{req}} = E_{\\text{pre}} + \\sum_{t=1}^{L} E_{\\text{step}}(t),\\qquad E_{\\text{step}} \\approx P_{\\text{idle}}\\cdot \\Delta t + \\kappa \\cdot B_{\\text{KV}}(t)$$</div>\n<p>其中 $B_{\\text{KV}}(t)$ 是第 $t$ 步实际搬运的 KV 字节数，$\\kappa$ 是每字节搬运对应的能量系数，$P_{\\text{idle}}$ 是空转功耗。这个式子的工程含义很直接：解码段能耗对生成长度 $L$ 是线性的，而策略提前终止就是把 $L$ 从 $L_{\\max}$ 截断到 $L_{\\text{eff}}$。举例，一个仓库级补全请求上下文 32K token、模型在 B200 上以 FP8 权重运行，若策略把平均生成长度从 512 截到 300，解码段能耗按上式近似下降四成，但预填段一分未省——这正是为什么单看总能耗下降比例会误导人：收益全部来自解码，而预填在长上下文场景里往往才是大头。</p>\n<p>代价面必须同时报：提前终止降低了 $L$，直接减少解码 FLOPs 与 KV 读取带宽，但也把 TTFT 之外的有效吞吐（tokens/s per request）拉低，因为同样的墙钟时间里产出更少 token。对连续批处理系统，单请求变短会改变批内 token 预算的分配，进而影响整批的 TPOT 稳定性。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-46\">四十六 · 硬件档位：没有档位就没有能耗数字</h3>\n<p>材料明确未给出硬件档位、数值精度与测量方法，这一条是本工作最硬的局限，也是读者读数字时第一件要查的事。能耗不是模型的固有属性，它是「模型 × 精度 × 档位 × 批 × 并发」的联合函数。同一个策略在 B200 单卡 FP8 与 GB200 NVL72 机柜级 FP4 上跑出的能耗下降比例不可比，因为分母本身就换了：前者权重读取占主导，后者在 NVLink 5 域内做张量并行与专家并行，通信功耗与 SM 空闲功耗占比完全不同。</p>\n<p>具体机制上，Blackwell 的 tcgen05 与 TMEM 让 MMA 的累加器驻留在张量内存里，减少寄存器与共享内存往返，这对预填段的能效是实质性的；而 2-SM MMA 让一对 SM 协同完成更大 tile，提升的是单位功耗的算力密度。NVFP4 把权重与激活压到 4 位块浮点，权重读取字节数降到 FP8 的一半、FP16 的四分之一，直接作用于上式里的 $\\kappa \\cdot B_{\\text{KV}}$ 与权重项。若论文的能耗是在 FP16 基线上测的，把它搬到 NVFP4 部署上，解码段的固定开销（空转功耗、调度开销）占比会上升，策略提前终止带来的相对收益反而被稀释——这是跨档位不可比的典型来源。</p>\n<p>读数字时的判断规则：先问「分母是什么」。若报告写「能耗降低 X%」，必须同时给出基线精度、卡型、是否含预填、是否含测试用例执行开销。材料里明确「生成结果需经测试用例校验，校验开销未计入能耗统计」，这意味着能耗口径只覆盖模型推理，不含 CPU 侧编译与运行测试的能量——在仓库级场景里，编译一次的能量可能不低于一次短解码，漏掉它会让能效结论偏乐观。</p>\n<p>表格给出读数的对照口径，而不是任何实测值：</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>材料是否给出</th><th>对读数的影响</th></tr></thead><tbody><tr><td>硬件档位</td><td>未给出</td><td>无法映射到 B200/B300/GB200 NVL72，跨平台不可比</td></tr><tr><td>数值精度</td><td>未给出</td><td>NVFP4/FP8 与否决定权重与 KV 字节数，直接改 $\\kappa$ 项</td></tr><tr><td>批大小与并发</td><td>未给出</td><td>无法分离单请求能耗与整批摊销，吞吐-能耗曲线缺失</td></tr><tr><td>上下文长度分布</td><td>未给出</td><td>预填占比未知，总能耗下降比例的解释力受限</td></tr><tr><td>测试用例开销</td><td>明确未计入</td><td>能耗口径偏窄，端到端能效被高估</td></tr></tbody></table>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-47\">四十七 · batch 与并发：能耗的分母陷阱</h3>\n<p>能耗指标有两种记法，一种是每请求能耗（J/request），一种是每 token 能耗（J/token），还有一种是每通过样本能耗（J/pass）。GREEN-CODE 的约束是功能正确率，所以最贴合的记法是 J/pass：只有通过测试的生成才计入有效产出。三种记法在批与并发变化时走向不同，混用就会得出互相矛盾的结论。</p>\n<p>机制上，连续批处理把不同请求的解码步拼进同一个前向，权重读取被摊薄，单 token 能耗随批增大而下降，但下降到某点后被 KV 读取与注意力计算顶住，因为每请求的 KV 字节数不随批缩小。设批内请求数为 $b$、每步权重字节 $W$、每请求 KV 字节 $K$，则单步能耗近似</p>\n<div class=\"formula\">$$E_{\\text{step}}(b) \\approx \\alpha W + \\beta\\, b K,\\qquad \\frac{E_{\\text{step}}(b)}{b} \\approx \\frac{\\alpha W}{b} + \\beta K$$</div>\n<p>右侧第二项与 $b$ 无关，这就是摊销的天花板。工程判断：在 B200 上跑 FP8 的 70B 级代码模型，权重项 $\\alpha W$ 在 $b$ 从 1 增到 32 时被摊掉大部分，再往上增批，单 token 能耗的边际改善迅速衰减，而 TPOT 因调度与显存压力开始变差。若论文的能耗是在固定小批下测的，它的「提前终止省能耗」结论在大批高并发下会被稀释：因为此时单步能耗里权重项已被摊薄，省下的 token 数对应的绝对能量变小。</p>\n<p>并发还牵动显存。提前终止释放的 KV 块可以回收到池子里给新请求用，这在 vLLM 的 PagedAttention 式分块管理下是实打实的容量收益：同样显存能容纳更多并发请求，从而抬高整批的 token 吞吐。但这条收益依赖 KV 分块与回收策略，材料未描述，因此不能把「生成长度缩短」直接换算成「并发上限提升」。一个具体例子：若每请求平均 KV 占用从 512 token 降到 300 token，在固定显存预算下理论并发上限按比例上升，但实际受限于调度器的块预留与碎片，收益要打折。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-48\">四十八 · 指标族：TTFT、TPOT、吞吐、功耗各自回答什么</h3>\n<p>四个指标回答四个不同问题，读论文数字时必须对号入座。TTFT 回答「用户等多久看到第一个 token」，它由预填段决定，与生成长度策略无关——GREEN-CODE 的提前终止对 TTFT 零贡献，这一点常被误读为「能效优化也改善了交互延迟」。TPOT 回答「出字多快」，它由解码段每步的 KV 读取与批内竞争决定；提前终止不改变 TPOT，只改变总时长 $L \\cdot \\text{TPOT}$。吞吐回答「单位时间服务多少 token 或多少请求」，它是批与调度的函数。功耗回答「瞬时或平均功率」，与利用率和精度强相关。</p>\n<p>把能耗与这些指标连起来的是能量-延迟积。对一次请求，若以 TPOT 为节奏、以 $L$ 为长度，则解码段时间 $T_{\\text{dec}} \\approx L \\cdot \\text{TPOT}$，能量 $E_{\\text{dec}} \\approx P_{\\text{avg}} \\cdot T_{\\text{dec}}$。提前终止同时压 $L$ 与 $T_{\\text{dec}}$，但 $P_{\\text{avg}}$ 未必下降——GPU 在短解码里可能更多处于低利用率高静态功耗区间，单位时间功率不降反升的比例效应会让 J/token 变差。这就是为什么只报总能耗下降而不报功率曲线的结论不可复现。</p>\n<p>具体例子：一个工具调用循环里，模型先生成一段短代码再触发执行，若策略在置信度高时截断，单次调用的 $L$ 缩短、$T_{\\text{dec}}$ 缩短，端到端延迟改善明显；但若该循环反复触发，每次预填都要重建 KV，预填能耗被重复计入，总能耗的下降幅度远小于单次请求的下降幅度。这说明指标必须按「会话」而非「单请求」聚合，否则会系统性高估收益。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-49\">四十九 · 哪些提升不可比：四条硬边界</h3>\n<p>第一条边界是精度。FP16 基线与 NVFP4 部署的能耗不可直接相减，因为权重与 KV 字节数差了一个数量级，$\\kappa$ 项整体缩放。第二条边界是硬件档位与拓扑：单卡、8 卡 NVLink 域、GB200 NVL72 机柜三种拓扑下，通信能耗与 SM 空闲占比不同，同一策略的相对收益不可移植。第三条边界是负载形态：材料未给出上下文长度分布，而预填与解码的能耗比例随上下文长度剧烈变化，短上下文场景里解码占主导，长上下文仓库级场景里预填占主导，同一组数字在两种负载下含义相反。第四条边界是质量口径：通过率阈值 $\\tau$ 未给出具体值，能耗是在什么质量水平下取得的未知，因此「省了能耗」不能与「没牺牲正确率」直接并列。</p>\n<p>形式化地，论文的目标是</p>\n<div class=\"formula\">$$\\min_{\\pi}\\ \\mathbb{E}_{x\\sim\\mathcal{D}}\\left[\\mathcal{E}(\\pi,x)\\right]\\quad \\text{s.t.}\\quad \\mathbb{E}_{x\\sim\\mathcal{D}}\\left[\\mathbb{1}\\{\\text{pass}(\\pi,x)\\}\\right]\\ge \\tau$$</div>\n<p>读这个式子要注意：$\\tau$ 是期望通过率的下界，不是逐样本保证。这意味着策略可以在部分样本上牺牲正确率换取能耗，只要总体期望达标。工程上这是有风险的——代码生成的任务分布长尾，少数难题上的失败可能对应高价值场景。因此任何「能耗下降」的数字都必须与 $\\tau$ 绑定阅读，脱离约束谈能耗没有意义。</p>\n<p>还有一个不可比来源是策略学习的反馈闭环。训练信号来自测试用例的通过标志，这意味着能耗与质量的联合评估依赖测试基础设施；在有测试的基准上测出的收益，搬到无测试的在线补全场景（只有接受/拒绝信号）时，策略的置信度判据失去校准依据，提前终止的阈值不再可信。这不是精度问题，是监督信号缺失导致的分布外行为，任何跨场景的数字搬运都要先问这一点。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-50\">五十 · 把口径写成可执行的采集清单</h3>\n<p>落到工程，读这篇论文的数字前应先建立自己的采集口径，再决定是否采信其结论。清单的核心是把每个数字标注四元组：精度、档位、批/并发、聚合粒度。缺任一项，该数字只能作定性参考。对 Blackwell 部署，建议在预填与解码之间插入显式分界打点，用 CUDA event 或框架的 profiling 钩子分别累计两段的时间与能量估算；能量可用板级功率采样乘以区间时长近似，但必须扣除空闲基线，否则低利用率区间的静态功耗会污染结论。</p>\n<p>伪代码思路如下，用于把论文的策略收益换算到自己的档位：</p>\n<ul>\n<li>对每个请求记录 $L_{\\text{eff}}$（实际生成长度）、$L_{\\max}$（策略上限）、预填 token 数、KV 字节峰值；</li>\n<li>按 $E_{\\text{req}} = E_{\\text{pre}} + L_{\\text{eff}} \\cdot \\bar{E}_{\\text{step}}$ 估算，其中 $\\bar{E}_{\\text{step}}$ 用本档位实测的单步能耗，而非论文数字；</li>\n<li>用 J/pass 而非 J/request 聚合，把未通过的生成计入分母之外的浪费项；</li>\n<li>对同一批请求跑关闭策略的对照，得到同档位下的相对收益，避免跨档位相减。</li>\n</ul>\n<p>代价面要诚实：这套采集本身引入 profiling 开销，逐请求打点会破坏连续批处理的流水，实际应在采样比例上做取舍，比如每 N 个请求采一次并做无偏估计。另一个工程判断是，若你的部署已用 NVFP4 权重加 FP8 KV，解码段的固定开销占比升高，GREEN-CODE 式的生成长度截断带来的相对能耗收益会比论文在 FP16 基线上报告的小；此时更值得投入的是 KV 缓存复用与分离式预填/解码的拓扑优化，而不是继续压生成长度。最终判断落在一点：能耗数字的可比性由口径四元组决定，而不是由下降百分比决定。</p>\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-51\">五十一 · 迁移的第一道门槛：策略的输入信号从哪来</h3>\n<p>GREEN-CODE 的策略在解码阶段决定\"继续生成还是提前终止\"，这个决策的输入是当前生成状态与置信度信号。把它迁到别的模型上，最先崩的不是模型权重，而是这个信号的可获得性。原方法依赖生成完成后运行测试用例得到的通过标志来构造训练反馈，也就是说策略学习环节的监督信号是<em>事后</em>的、需要执行环境的。迁到一个没有测试用例的场景——比如 IDE 里的行内补全、或者没有单测的遗留仓库——反馈回路直接断掉，策略无法继续更新，只能退化成固定的长度阈值。</p>\n<p>工程上的处理是把事后信号换成事前代理信号：用模型自身的 token 对数概率、熵、或者草稿模型与目标模型的一致性作为置信度代理，把\"是否继续\"变成在线可判定的问题。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{stop}_t = \\mathbb{1}\\left[\\;H_t &lt; h_0 \\;\\wedge\\; \\text{prefix}(y_{\\le t}) \\text{ parses} \\;\\wedge\\; t \\ge t_{\\min}\\right]$$</div>\n<p>其中 $H_t$ 是当前步的熵，$h_0$ 是阈值，$t_{\\min}$ 是语法上允许终止的最短长度。这个替换的代价是：代理信号与真实通过率之间存在偏差，阈值定得松则通过率下降，定得紧则省不下能耗。迁移时必须重新标定 $h_0$，而标定本身需要一批带测试的样本，这就构成了迁移的启动成本。对 Blackwell 部署而言，这个标定过程可以离线跑在 B200 上，用较小的批做快速扫描，但标定结果与线上模型版本绑定，模型一换就要重来。</p>\n<p>具体例子：把一个在 Python 单文件题目上训练的策略迁到 TypeScript 仓库级补全，语法解析器不同、可终止点不同、测试反馈缺失，三个条件同时变化，原阈值直接失效。判断是：这类迁移不是调参问题，是信号源重建问题。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-52\">五十二 · 能耗度量的跨平台不可比性</h3>\n<p>论文的能耗度量覆盖预填与解码两阶段，但材料未给出硬件档位、数值精度与测量方法。这意味着它的能耗数字是<em>相对量</em>而非绝对量，迁移到 Blackwell 上时不能直接换算。原因在于预填与解码的能耗结构在 SM100 上被彻底改写：预填是大矩阵乘、受 tcgen05 与 TMEM 带宽支配，解码是逐 token 的小算子、受 KV cache 读取与发射开销支配。同一份策略在两个平台上省下的\"token 数\"相同，但映射到焦耳数完全不同。</p>\n<p>可迁移的是<em>结构</em>而不是<em>数值</em>。把能耗拆成可加的两项：</p>\n<div class=\"formula\">$$E(\\pi,x) \\approx \\underbrace{c_{\\text{pre}}\\cdot L_{\\text{ctx}}}_{\\text{预填}} + \\underbrace{c_{\\text{dec}}\\cdot N_{\\text{gen}}(\\pi,x)}_{\\text{解码}}$$</div>\n<p>策略只影响 $N_{\\text{gen}}$，即生成长度，而 $c_{\\text{pre}}$ 与 $c_{\\text{dec}}$ 是平台常数。迁移时要做的是在新平台上重新测这两个常数，而不是搬用旧系数。在 B200 上，$c_{\\text{dec}}$ 会随批大小显著变化——连续批处理把多个请求的解码步拼在一起，单 token 的边际能耗被摊薄，此时\"少生成几个 token\"的节能收益被稀释；而在批大小为 1 的延迟敏感场景，$c_{\\text{dec}}$ 高，提前终止的收益被放大。判断是：这套策略的能效收益与批调度强耦合，脱离批配置谈节能比例没有意义。</p>\n<p>具体代价：如果线上用大批连续批处理追求吞吐，策略省下的 token 数换算成整机功耗的下降幅度有限，因为解码能耗已被批处理摊薄到接近预填占比；反过来，在分离式预填/解码架构里，解码实例的批较小，策略的收益更明显。迁移前必须先确定部署形态，否则能耗结论无法落地。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-53\">五十三 · 与量化、KV cache 管理的叠加关系</h3>\n<p>论文未涉及 NVFP4/FP8 量化、分离式预填/解码或投机解码。迁移到 Blackwell 时，这些机制不是可选项而是默认项，它们与\"提前终止\"策略之间存在交互，方向不一定一致。</p>\n<ul>\n<li><strong>量化</strong>：NVFP4 把权重与激活压到 4 位，单 token 解码的算力代价下降，$c_{\\text{dec}}$ 变小，提前终止的相对收益随之变小。但量化会改变模型输出的置信度分布，熵阈值 $h_0$ 需要重标定，否则策略会在量化后过早终止、拉低通过率。</li>\n<li><strong>KV cache 管理</strong>：长上下文仓库级补全里，预填建立的 KV 缓存是显存大头。策略缩短生成长度只减解码侧，不减预填侧；若上下文本身很长，预填能耗占比高，策略的节能上限被压住。这与 CodeComp 那类结构化 KV 压缩是正交手段，两者叠加才有意义，单独用策略在长上下文场景收益有限。</li>\n<li><strong>投机解码</strong>：投机解码用草稿模型批量提议、目标模型验证，本身就在改变\"每 token 的验证代价\"与\"接受率\"。策略若在投机解码之上再叠加提前终止，两个控制回路会互相干扰——草稿模型被提前终止截断，接受率统计失真。迁移时需要把终止决策放在验证之后而非提议阶段。</li>\n</ul>\n<p>判断是：这套方法在裸模型上是干净的，一旦叠上 Blackwell 的标配推理机制，它从\"独立优化\"退化为\"调度层的一个旋钮\"，收益被其他机制部分吃掉。规模上限也在这里：当量化把解码代价压到很低、KV 压缩把预填代价压到很低时，剩下的可优化空间就是生成长度本身，而长度受正确率约束，不能无限压。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-54\">五十四 · 领域迁移：哪些代码形态不适用</h3>\n<p>策略的隐含假设是\"代码生成存在冗余长度\"，即模型倾向于生成比必要更长的输出，提前终止可以砍掉这部分。这个假设在单文件算法题上成立，因为通过测试即完成，多余的解释性 token 与防御性代码是浪费。但在其他代码形态上，假设不成立或反向成立。</p>\n<table class=\"mini\">\n<thead><tr><th>代码形态</th><th>冗余长度假设</th><th>迁移判断</th></tr></thead>\n<tbody>\n<tr><td>单文件算法题</td><td>成立，测试判定明确</td><td>可直接迁移，需重标定阈值</td></tr>\n<tr><td>仓库级补全</td><td>弱，上下文依赖强</td><td>需结合 KV 压缩，收益被预填占比稀释</td></tr>\n<tr><td>工具调用循环</td><td>不成立，长度由协议决定</td><td>不适用，终止点由工具返回驱动</td></tr>\n<tr><td>测试生成</td><td>反向，短输出覆盖不足</td><td>不适用，提前终止直接降低覆盖率</td></tr>\n<tr><td>重构/迁移</td><td>不成立，需完整改写</td><td>不适用，截断产生不可编译代码</td></tr>\n</tbody>\n</table>\n<p>工具调用循环是最典型的边界：生成长度不由模型自由决定，而由工具 schema 与返回结构约束，提前终止只会产生不完整的调用参数。测试生成则是反向边界——短测试通过率高但覆盖低，用通过率作约束会奖励\"生成最少的断言\"，这与能效目标同向却与工程质量反向。判断是：这套方法适用于\"有明确功能判定且输出长度有冗余\"的场景，超出这个范围就是误用。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-55\">五十五 · 规模上限与容量规划的落点</h3>\n<p>把策略放进容量规划，要回答的是：它能把单请求的平均能耗压到什么程度，以及这个压缩是否随规模线性保持。答案是否定的，原因在预填占比。设上下文长度为 $L_{\\text{ctx}}$、生成长度为 $N_{\\text{gen}}$，策略把 $N_{\\text{gen}}$ 压到 $N'_{\\text{gen}}$，则节能比例为：</p>\n<div class=\"formula\">$$\\eta = \\frac{c_{\\text{dec}}(N_{\\text{gen}}-N'_{\\text{gen}})}{c_{\\text{pre}}L_{\\text{ctx}}+c_{\\text{dec}}N_{\\text{gen}}}$$</div>\n<p>当 $L_{\\text{ctx}}$ 增大，分母被预填项主导，$\\eta$ 趋近于零。仓库级补全的上下文动辄数万 token，此时策略的节能上限被结构性锁死。这不是策略本身的问题，是优化变量选错了侧——要突破这个上限，必须把优化变量从解码长度扩展到预填侧的 KV 复用与压缩，也就是把 GREEN-CODE 的框架与 KV cache 管理、前缀缓存结合。</p>\n<p>规模上限还体现在策略学习的样本效率上：反馈信号需要测试执行，测试执行本身消耗 CPU 与时间，在大规模部署里这部分开销不计入论文的能耗统计，但会计入集群的总体拥有成本。判断是：这套方法适合作为推理栈里的一个轻量旋钮，适合在延迟敏感、批较小的解码实例上启用；不适合作为容量规划的主杠杆，主杠杆仍是量化、KV 压缩与批调度。迁移的正确姿势是把它当作调度层的一个可配置项，与硬件档位、批配置、量化方案一起标定，而不是当作一个可以跨平台搬运的固定收益。</p>\n\n<h3 id=\"paper-green-code-learning-to-optimize-ener-2025-sec-56\">五十六 · 迁移到别的模型与领域时，先看哪几个耦合点会断</h3>\n<p>这套方案的优化变量落在解码阶段的生成长度与策略选择上，因此迁移时最先断掉的不是模型结构，而是策略与验证器之间的耦合。策略学习的反馈信号来自对生成代码运行测试用例得到的通过标志，目标形式为 <span class=\"formula\">$$\\min_{\\pi}\\ \\mathbb{E}_{x\\sim\\mathcal{D}}\\left[\\mathcal{E}(\\pi,x)\\right]\\quad \\text{s.t.}\\quad \\mathbb{E}_{x\\sim\\mathcal{D}}\\left[\\mathbb{1}\\{\\text{pass}(\\pi,x)\\}\\right]\\ge \\tau$$</span>，其中约束项完全依赖可执行的判定。迁到没有测试用例的场景——仓库级代码补全、单行续写、注释生成——约束项无从计算，策略退化为无约束的提前终止，正确率不再有下界保证。迁到非代码领域（结构化抽取、多轮工具调用、长文摘要）时，判定器要么换成人工标注、要么换成模型裁判，反馈延迟从毫秒级测试执行变成秒级甚至离线批处理，策略更新周期被拉长，能耗优化的闭环从在线退化为离线。工程判断很直接：先确认目标领域是否存在廉价、确定、可自动化的通过判定；若没有，这套方法只能作为离线调参的启发式，不能作为在线调度器。</p>\n<p>第二个耦合点是能耗度量的口径。论文的度量覆盖预填与解码两阶段，但材料未给出硬件档位、数值精度与测量方法，因此能耗数值本身不具备跨平台可比性。迁移到 Blackwell 时，这个口径必须重写：预填阶段的能耗主要由上下文长度与批内 token 总量决定，走的是 tcgen05 大块矩阵乘与 TMEM 累加路径，NVFP4/FP8 量化会直接改变单位 token 的能量；解码阶段则是逐 token 的 2-SM MMA 与小批量访存，权重带宽与 KV cache 读取占主导，能耗对批大小远比预填敏感。把论文里未标定档位的能耗曲线直接搬到 B200 上做容量规划，误差会同时来自精度档位与批调度两个方向。可迁移的是“预填/解码分开计量”这一结构，不可迁移的是具体数值；迁移时必须重新标定单位 token 能量，并把它写成硬件档位、精度、批大小的三元函数，否则 SLO 与功耗预算无法对齐。</p>\n<p>第三个边界是规模上限与失效条件。策略只在生成长度维度做控制，不触及量化、分离式预填/解码、投机解码等机制，因此它的收益上界被“不必要的 token 占比”锁死：当模型本身在长上下文仓库级补全中大量 token 是必需的（跨文件符号解析、类型推导），提前终止的空间迅速收窄，能耗下降趋于饱和，而 KV cache 的显存占用与带宽开销并不因少生成几个 token 而缓解。此时真正的瓶颈转移到 KV 缓存管理与预填复用，属于本方案未覆盖的层面。反过来，在短问题、强测试反馈、低并发的小规模部署里，该方案代价低、见效快；一旦进入 NVL72 级别的多副本服务，策略决策必须与连续批处理调度器协同，否则提前终止造成的批内长度抖动会拉低整体吞吐，把省下的解码能耗又还给调度开销。判断标准是：单位请求的必需 token 占比高、或批内长度方差大时，不应把能效预算押在长度策略上。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>可直接沿用</th><th>必须重做</th><th>典型失效</th></tr></thead><tbody><tr><td>判定器</td><td>预填/解码分段计量结构</td><td>通过率阈值 τ 与判定成本</td><td>无测试用例的补全场景</td></tr><tr><td>硬件口径</td><td>长度控制接口</td><td>单位 token 能量标定（精度/批大小）</td><td>跨档位能耗不可比</td></tr><tr><td>规模</td><td>单副本低并发调优</td><td>与连续批处理调度协同</td><td>批内长度抖动吞噬吞吐</td></tr></tbody></table>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">GREEN-CODE: Learning to </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Optimize Energy…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · GREEN-CODE: Learning to… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>代码生成编程问题数据集（材料未给出具体名称与规模）</td></tr><tr><td>基线</td><td>未给出具体基线方法</td></tr><tr><td>主要结果</td><td>论文报告在代码生成任务上通过能效优化策略可在保持功能正确性的同时降低推理能…</td></tr><tr><td>消融</td><td>材料未给出消融实验的具体设置与结果，无法判断各组件对能效与通过率的独立贡献。</td></tr><tr><td>局限</td><td>材料未给出实验的硬件档位、批大小、上下文长度分布与能耗测量方法细节，因此能…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-green-code-learning-to-optimize-ener-2025 · 共 9 个片段</p>\n";break;}}})();
